{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE or REPLACE table snitch_db.maplemonk.offline_long_tail_Replen as With Perfumes as( WITH stores_perf AS ( SELECT DISTINCT marketplace_mapped, branch_code FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE marketplace_mapped NOT IN ( \'SNITCH - WH - B2B\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\', \'SNITCH - WH - RAJASTHAN\', \'SNITCH - WH - U.P\', \'SNITCH - WH - M P\', \'SNITCH - WH - GUJARAT\', \'SNITCH - WH - MAHARASTRA\' ) ), perfumes_list AS ( SELECT DISTINCT (CASE WHEN upper(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END) AS sku_group FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'%FR%\' AND UPPER(\"Item SkuCode\") NOT LIKE \'%T%\' GROUP BY CASE WHEN upper(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END HAVING COALESCE(SUM(inventory), 0) > 0 ), perfumesxstores AS ( SELECT s.marketplace_mapped, s.branch_code, p.sku_group FROM stores_perf s CROSS JOIN perfumes_list p ), RequiredQuantities_perf AS ( Select * from ( SELECT a.*, h.dept, h.perfume as Status, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,101,99,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END AS store_rank, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END AS is_new_combination, COALESCE(b.new_category, \'Perfumes\') AS new_category, SUM(COALESCE(SALES_LAST_7_DAYS, 0)) AS SALE_7, SUM(COALESCE(SALES_LAST_15_DAYS, 0)) AS SALE_15, SUM(COALESCE(SALES_LAST_30_DAYS, 0)) AS SALE_30, SUM(COALESCE(INVENTORY, 0)) AS INV, SUM(COALESCE(jit_qty, 0)) AS jit_qty, SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) AS ADJUSTED_QUANTITY, CASE WHEN a.sku_group IN (\'4MSFR0931\',\'4MSFR0930\') THEN SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 2, 12) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 2, 12) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) WHEN SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) < 15 THEN 0 WHEN SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) BETWEEN 15 AND 35 THEN 24 WHEN SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) > 35 AND SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) <= 10000 THEN 48 ELSE SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) END AS REQUIRED_QUANTITY FROM perfumesxstores a LEFT JOIN ( SELECT *, UPPER(sku_group) AS upper_sku_group FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ) b ON a.marketplace_mapped = b.marketplace_mapped AND a.branch_code = b.branch_code AND a.sku_group = b.upper_sku_group LEFT JOIN ( SELECT DISTINCT branch_code, PERFUME, \"Perfume(Dept)\" as Dept FROM snitch_db.maplemonk.offline_long_tail_sheet1 ) h ON a.branch_code = h.branch_code WHERE a.branch_code IS NOT NULL AND lower(h.perfume) = \'yes\' GROUP BY 1,2,3,4,5,6,7,8 ) order by sale_7 desc ) , WarehouseInfo_perf AS ( WITH data AS ( SELECT \"Item SkuCode\" AS sku, FACILITY, COALESCE(SUM(inventory), 0) AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY in (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(sku) LIKE \'%FR%\' AND UPPER(sku) NOT LIKE \'%T%\' GROUP BY sku, FACILITY ) SELECT sku, facility, SUM(qty) as units_on_hand FROM data WHERE qty > 0 GROUP BY sku, facility ), warehouse_preference AS ( SELECT r.sku_group AS SKU_CODE, r.branch_code, r.REQUIRED_QUANTITY AS REPLEN_UNITS, r.store_rank, w.facility, w.units_on_hand, CASE WHEN r.store_rank = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'North\' AND w.facility != \'SAPL-NORTH-TAURU\' THEN 2 WHEN r.store_rank = \'South\' AND w.facility != \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM RequiredQuantities_perf r JOIN WarehouseInfo_perf w ON r.sku_group = w.sku ), ordered_warehouses AS ( SELECT *, ROW_NUMBER() OVER( PARTITION BY SKU_CODE, branch_code ORDER BY base_priority ASC, units_on_hand DESC ) AS warehouse_order FROM warehouse_preference ), allocation AS ( SELECT o.SKU_CODE, o.branch_code, o.store_rank, o.facility, o.warehouse_order, o.REPLEN_UNITS, o.units_on_hand, CASE WHEN o.units_on_hand >= o.REPLEN_UNITS THEN o.REPLEN_UNITS ELSE o.units_on_hand END AS allocated_units, o.REPLEN_UNITS - SUM( CASE WHEN o.units_on_hand >= o.REPLEN_UNITS THEN o.REPLEN_UNITS ELSE o.units_on_hand END ) OVER( PARTITION BY o.SKU_CODE, o.branch_code ORDER BY o.warehouse_order ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS remaining_units FROM ordered_warehouses o ), final_allocation AS ( SELECT SKU_CODE, branch_code, store_rank, facility, warehouse_order, CASE WHEN remaining_units < 0 THEN allocated_units + remaining_units ELSE allocated_units END AS allocated_units FROM allocation WHERE allocated_units > 0 ), capped_allocation AS ( SELECT f.SKU_CODE, f.branch_code, f.store_rank, f.facility, f.warehouse_order, f.allocated_units, SUM(f.allocated_units) OVER( PARTITION BY f.SKU_CODE, f.facility ORDER BY f.warehouse_order, f.branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_allocated, w.units_on_hand FROM final_allocation f JOIN WarehouseInfo_perf w ON f.SKU_CODE = w.sku AND f.facility = w.facility ), balanced_allocation AS ( SELECT SKU_CODE, branch_code, store_rank, facility, warehouse_order, CASE WHEN cum_allocated <= units_on_hand THEN allocated_units WHEN cum_allocated - allocated_units < units_on_hand THEN units_on_hand - (cum_allocated - allocated_units) ELSE 0 END AS allocated_units FROM capped_allocation WHERE allocated_units > 0 ) SELECT * FROM balanced_allocation WHERE allocated_units > 0 ORDER BY SKU_CODE, branch_code, warehouse_order ), bagss as ( WITH stores_perf AS ( SELECT DISTINCT marketplace_mapped, branch_code FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE marketplace_mapped NOT IN ( \'SNITCH - WH - B2B\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\', \'SNITCH - WH - RAJASTHAN\', \'SNITCH - WH - U.P\', \'SNITCH - WH - M P\', \'SNITCH - WH - GUJARAT\', \'SNITCH - WH - MAHARASTRA\' ) ), bags_list AS ( SELECT DISTINCT \"Item SkuCode\" AS sku_group FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'BP%\' GROUP BY \"Item SkuCode\" HAVING COALESCE(SUM(inventory), 0) > 0 ), bagsxstores AS ( SELECT s.marketplace_mapped, s.branch_code, p.sku_group FROM stores_perf s CROSS JOIN bags_list p ), RequiredQuantities_bags AS ( Select * from ( SELECT a.*, h.dept, h.BAGS AS Status, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,101,99,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END AS store_rank, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END AS is_new_combination, COALESCE(b.new_category, \'Bags\') AS new_category, SUM(COALESCE(SALES_LAST_7_DAYS, 0)) AS SALE_7, SUM(COALESCE(SALES_LAST_15_DAYS, 0)) AS SALE_15, SUM(COALESCE(SALES_LAST_30_DAYS, 0)) AS SALE_30, SUM(COALESCE(INVENTORY, 0)) AS INV, SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) AS REQUIRED_QUANTITY FROM bagsxstores a LEFT JOIN ( SELECT *, UPPER(sku_group) AS upper_sku_group FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ) b ON a.marketplace_mapped = b.marketplace_mapped AND a.branch_code = b.branch_code AND a.sku_group = b.upper_sku_group LEFT JOIN ( SELECT DISTINCT branch_code, BAGS, \"Bags(Dept)\" as Dept FROM snitch_db.maplemonk.offline_long_tail_sheet1 ) h ON a.branch_code = h.branch_code WHERE a.branch_code IS NOT NULL AND lower(h.BAGS) = \'yes\' GROUP BY 1,2,3,4,5,6,7,8 ) Order by SALE_7 desc ), WarehouseInfo_bags AS ( WITH data AS ( SELECT \"Item SkuCode\" AS sku, FACILITY, COALESCE(SUM(inventory), 0) AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(sku) LIKE \'BP%\' GROUP BY sku, FACILITY ) SELECT sku, facility, SUM(qty) AS units_on_hand FROM data WHERE qty > 0 GROUP BY sku, facility ), warehouse_preference AS ( SELECT r.sku_group AS SKU_CODE, r.branch_code, r.REQUIRED_QUANTITY AS REPLEN_UNITS, r.store_rank, w.facility, w.units_on_hand, CASE WHEN r.store_rank = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'North\' AND w.facility != \'SAPL-NORTH-TAURU\' THEN 2 WHEN r.store_rank = \'South\' AND w.facility != \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM RequiredQuantities_bags r JOIN WarehouseInfo_bags w ON r.sku_group = w.sku ), ordered_warehouses AS ( SELECT *, ROW_NUMBER() OVER( PARTITION BY SKU_CODE, branch_code ORDER BY base_priority ASC, units_on_hand DESC ) AS warehouse_order FROM warehouse_preference ), allocation AS ( SELECT o.SKU_CODE, o.branch_code, o.store_rank, o.facility, o.warehouse_order, o.REPLEN_UNITS, o.units_on_hand, CASE WHEN o.units_on_hand >= o.REPLEN_UNITS THEN o.REPLEN_UNITS ELSE o.units_on_hand END AS allocated_units, o.REPLEN_UNITS - SUM( CASE WHEN o.units_on_hand >= o.REPLEN_UNITS THEN o.REPLEN_UNITS ELSE o.units_on_hand END ) OVER( PARTITION BY o.SKU_CODE, o.branch_code ORDER BY o.warehouse_order ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS remaining_units FROM ordered_warehouses o ), final_allocation AS ( SELECT SKU_CODE, branch_code, store_rank, facility, warehouse_order, CASE WHEN remaining_units < 0 THEN allocated_units + remaining_units ELSE allocated_units END AS allocated_units FROM allocation WHERE allocated_units > 0 ), capped_allocation AS ( SELECT f.SKU_CODE, f.branch_code, f.store_rank, f.facility, f.warehouse_order, f.allocated_units, SUM(f.allocated_units) OVER( PARTITION BY f.SKU_CODE, f.facility ORDER BY f.warehouse_order, f.branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_allocated, w.units_on_hand FROM final_allocation f JOIN WarehouseInfo_bags w ON f.SKU_CODE = w.sku AND f.facility = w.facility ), balanced_allocation AS ( SELECT SKU_CODE, branch_code, store_rank, facility, warehouse_order, CASE WHEN cum_allocated <= units_on_hand THEN allocated_units WHEN cum_allocated - allocated_units < units_on_hand THEN units_on_hand - (cum_allocated - allocated_units) ELSE 0 END AS allocated_units FROM capped_allocation WHERE allocated_units > 0 ) SELECT * FROM balanced_allocation WHERE allocated_units > 0 ORDER BY SKU_CODE, branch_code, warehouse_order ), Sunglasses as ( WITH stores_perf AS ( SELECT DISTINCT marketplace_mapped, branch_code FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE marketplace_mapped NOT IN ( \'SNITCH - WH - B2B\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\', \'SNITCH - WH - RAJASTHAN\', \'SNITCH - WH - U.P\', \'SNITCH - WH - M P\', \'SNITCH - WH - GUJARAT\', \'SNITCH - WH - MAHARASTRA\' ) ), bags_list AS ( SELECT DISTINCT \"Item SkuCode\" AS sku_group FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'SN%\' GROUP BY \"Item SkuCode\" HAVING COALESCE(SUM(inventory), 0) > 0 ), bagsxstores AS ( SELECT s.marketplace_mapped, s.branch_code, p.sku_group FROM stores_perf s CROSS JOIN bags_list p ), RequiredQuantities_bags AS ( Select * from ( SELECT a.*, h.dept, h.SUNGLASSES AS Status, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,101,99,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END AS store_rank, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END AS is_new_combination, COALESCE(b.new_category, \'Bags\') AS new_category, SUM(COALESCE(SALES_LAST_7_DAYS, 0)) AS SALE_7, SUM(COALESCE(SALES_LAST_15_DAYS, 0)) AS SALE_15, SUM(COALESCE(SALES_LAST_30_DAYS, 0)) AS SALE_30, SUM(COALESCE(INVENTORY, 0)) AS INV, SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) AS REQUIRED_QUANTITY FROM bagsxstores a LEFT JOIN ( SELECT *, UPPER(sku_group) AS upper_sku_group FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ) b ON a.marketplace_mapped = b.marketplace_mapped AND a.branch_code = b.branch_code AND a.sku_group = b.upper_sku_group LEFT JOIN ( SELECT DISTINCT branch_code, SUNGLASSES, \"Sunglasses(Dept)\" as Dept FROM snitch_db.maplemonk.offline_long_tail_sheet1 ) h ON a.branch_code = h.branch_code WHERE a.branch_code IS NOT NULL AND lower(h.SUNGLASSES) = \'yes\' GROUP BY 1,2,3,4,5,6,7,8 ) order by SALE_7 desc ), WarehouseInfo_bags AS ( WITH data AS ( SELECT \"Item SkuCode\" AS sku, FACILITY, COALESCE(SUM(inventory), 0) AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(sku) LIKE \'SN%\' GROUP BY sku, FACILITY ) SELECT sku, facility, SUM(qty) AS units_on_hand FROM data WHERE qty > 0 GROUP BY sku, facility ), warehouse_preference AS ( SELECT r.sku_group AS SKU_CODE, r.branch_code, r.REQUIRED_QUANTITY AS REPLEN_UNITS, r.store_rank, w.facility, w.units_on_hand, CASE WHEN r.store_rank = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'North\' AND w.facility != \'SAPL-NORTH-TAURU\' THEN 2 WHEN r.store_rank = \'South\' AND w.facility != \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM RequiredQuantities_bags r JOIN WarehouseInfo_bags w ON r.sku_group = w.sku ), ordered_warehouses AS ( SELECT *, ROW_NUMBER() OVER( PARTITION BY SKU_CODE, branch_code ORDER BY base_priority ASC, units_on_hand DESC ) AS warehouse_order FROM warehouse_preference ), allocation AS ( SELECT o.SKU_CODE, o.branch_code, o.store_rank, o.facility, o.warehouse_order, o.REPLEN_UNITS, o.units_on_hand, CASE WHEN o.units_on_hand >= o.REPLEN_UNITS THEN o.REPLEN_UNITS ELSE o.units_on_hand END AS allocated_units, o.REPLEN_UNITS - SUM( CASE WHEN o.units_on_hand >= o.REPLEN_UNITS THEN o.REPLEN_UNITS ELSE o.units_on_hand END ) OVER( PARTITION BY o.SKU_CODE, o.branch_code ORDER BY o.warehouse_order ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS remaining_units FROM ordered_warehouses o ), final_allocation AS ( SELECT SKU_CODE, branch_code, store_rank, facility, warehouse_order, CASE WHEN remaining_units < 0 THEN allocated_units + remaining_units ELSE allocated_units END AS allocated_units FROM allocation WHERE allocated_units > 0 ), capped_allocation AS ( SELECT f.SKU_CODE, f.branch_code, f.store_rank, f.facility, f.warehouse_order, f.allocated_units, SUM(f.allocated_units) OVER( PARTITION BY f.SKU_CODE, f.facility ORDER BY f.warehouse_order, f.branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_allocated, w.units_on_hand FROM final_allocation f JOIN WarehouseInfo_bags w ON f.SKU_CODE = w.sku AND f.facility = w.facility ), balanced_allocation AS ( SELECT SKU_CODE, branch_code, store_rank, facility, warehouse_order, CASE WHEN cum_allocated <= units_on_hand THEN allocated_units WHEN cum_allocated - allocated_units < units_on_hand THEN units_on_hand - (cum_allocated - allocated_units) ELSE 0 END AS allocated_units FROM capped_allocation WHERE allocated_units > 0 ) SELECT * FROM balanced_allocation WHERE allocated_units > 0 ORDER BY SKU_CODE, branch_code, warehouse_order ), Belts as ( WITH stores_perf AS ( SELECT DISTINCT marketplace_mapped, branch_code FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE marketplace_mapped NOT IN ( \'SNITCH - WH - B2B\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\', \'SNITCH - WH - RAJASTHAN\', \'SNITCH - WH - U.P\', \'SNITCH - WH - M P\', \'SNITCH - WH - GUJARAT\', \'SNITCH - WH - MAHARASTRA\' ) ), belts_list AS ( SELECT DISTINCT ( CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END ) AS sku_group FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'%MBL%\' GROUP BY CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END HAVING COALESCE(SUM(inventory), 0) > 0 ), beltsxstores AS ( SELECT s.marketplace_mapped, s.branch_code, p.sku_group FROM stores_perf s CROSS JOIN belts_list p ), RequiredQuantities_belts AS ( Select * from ( SELECT a.marketplace_mapped, a.branch_code, a.sku_group, h.dept, h.BELTS AS status, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,99,101,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END AS store_rank, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END AS is_new_combination, COALESCE(b.new_category, \'Belts\') AS new_category, SUM(COALESCE(SALES_LAST_7_DAYS, 0)) AS sale_7, SUM(COALESCE(SALES_LAST_15_DAYS, 0)) AS sale_15, SUM(COALESCE(SALES_LAST_30_DAYS, 0)) AS sale_30, SUM(COALESCE(INVENTORY, 0)) AS inventory, SUM(COALESCE(JIT_QTY, 0)) AS jit_qty, SUM(COALESCE(S_UNITS + JIT_S_UNITS, 0)) AS s_units, SUM(COALESCE(M_UNITS + JIT_M_UNITS, 0)) AS m_units, SUM(COALESCE(L_UNITS + JIT_L_UNITS, 0)) AS l_units, SUM(COALESCE(XL_UNITS + JIT_XL_UNITS, 0)) AS xl_units, SUM(COALESCE(XXL_UNITS + JIT_2XL_UNITS, 0)) AS xxl_units FROM beltsxstores a LEFT JOIN ( SELECT *, UPPER(sku_group) AS upper_sku_group FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ) b ON a.marketplace_mapped = b.marketplace_mapped AND a.branch_code = b.branch_code AND a.sku_group = b.upper_sku_group LEFT JOIN ( SELECT DISTINCT branch_code, BELTS, \"Belts(Dept)\" AS dept FROM snitch_db.maplemonk.offline_long_tail_sheet1 ) h ON a.branch_code = h.branch_code WHERE a.branch_code IS NOT NULL AND LOWER(h.BELTS) = \'yes\' GROUP BY a.marketplace_mapped, a.branch_code, a.sku_group, h.dept, h.BELTS, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,99,101,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END, COALESCE(b.new_category, \'Belts\') ) order by sale_7 desc ), size_dist AS ( SELECT r.*, r.dept::int AS dept_int, d.size, d.weight, d.priority, (r.dept::int * d.weight) / 8.0 AS raw_desired, FLOOR((r.dept::int * d.weight) / 8.0) AS base_desired, ((r.dept::int * d.weight) / 8.0) - FLOOR((r.dept::int * d.weight) / 8.0) AS frac_part FROM RequiredQuantities_belts r JOIN ( SELECT \'M\' AS size, 2 AS weight, 1 AS priority UNION ALL SELECT \'L\', 2, 2 UNION ALL SELECT \'XL\',2, 3 UNION ALL SELECT \'S\', 1, 4 UNION ALL SELECT \'XXL\',1, 5 ) d ), size_dist_with_remainder AS ( SELECT sd.*, SUM(sd.base_desired) OVER ( PARTITION BY sd.marketplace_mapped, sd.branch_code, sd.sku_group ) AS sum_base, (sd.dept_int - SUM(sd.base_desired) OVER ( PARTITION BY sd.marketplace_mapped, sd.branch_code, sd.sku_group )) AS remainder, ROW_NUMBER() OVER ( PARTITION BY sd.marketplace_mapped, sd.branch_code, sd.sku_group ORDER BY sd.frac_part DESC, sd.priority ASC ) AS frac_rank FROM size_dist sd ), size_target AS ( SELECT marketplace_mapped, branch_code, sku_group, size, base_desired + CASE WHEN frac_rank <= GREATEST(remainder, 0) THEN 1 ELSE 0 END AS desired_units FROM size_dist_with_remainder ), size_with_current AS ( SELECT st.marketplace_mapped, st.branch_code, st.sku_group, st.size, st.desired_units, CASE st.size WHEN \'S\' THEN r.s_units WHEN \'M\' THEN r.m_units WHEN \'L\' THEN r.l_units WHEN \'XL\' THEN r.xl_units WHEN \'XXL\' THEN r.xxl_units END AS current_units FROM size_target st JOIN RequiredQuantities_belts r ON r.marketplace_mapped = st.marketplace_mapped AND r.branch_code = st.branch_code AND r.sku_group = st.sku_group ), size_requirements AS ( SELECT marketplace_mapped, branch_code, sku_group, UPPER(size) AS size, desired_units, current_units, GREATEST(desired_units - COALESCE(current_units, 0), 0) AS required_units FROM size_with_current ) , WarehouseInfo_belts AS ( WITH data AS ( SELECT \"Item SkuCode\" AS sku_full, FACILITY, COALESCE(SUM(inventory), 0) AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'%MBL%\' GROUP BY 1,2 ), normalized AS ( SELECT sku_full, facility, qty, CASE WHEN UPPER(sku_full) LIKE \'4C%\' THEN SPLIT_PART(sku_full, \'-\', 1) || \'-\' || SPLIT_PART(sku_full, \'-\', 2) || \'-\' || SPLIT_PART(sku_full, \'-\', 3) WHEN POSITION(\'-\' IN sku_full) > 0 THEN SPLIT_PART(sku_full, \'-\', 1) || \'-\' || SPLIT_PART(sku_full, \'-\', 2) ELSE sku_full END AS sku_group, UPPER( CASE REGEXP_SUBSTR(sku_full, \'[^-]+$\') WHEN \'30\' THEN \'S\' WHEN \'32\' THEN \'M\' WHEN \'34\' THEN \'L\' WHEN \'36\' THEN \'XL\' WHEN \'38\' THEN \'XXL\' WHEN \'40\' THEN \'XXL\' ELSE NULL END ) AS size_label FROM data ) SELECT sku_group, size_label, facility, SUM(qty) AS units_on_hand FROM normalized WHERE size_label IS NOT NULL AND qty > 0 GROUP BY sku_group, size_label, facility ), warehouse_preference AS ( SELECT sr.marketplace_mapped, sr.branch_code, sr.sku_group, UPPER(sr.size) AS size_label, r.store_rank, sr.required_units AS replen_units, w.facility, w.units_on_hand, CASE WHEN r.store_rank = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'North\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 2 WHEN r.store_rank = \'South\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM size_requirements sr JOIN RequiredQuantities_belts r ON r.marketplace_mapped = sr.marketplace_mapped AND r.branch_code = sr.branch_code AND r.sku_group = sr.sku_group JOIN WarehouseInfo_belts w ON w.sku_group = sr.sku_group AND w.size_label = UPPER(sr.size) ), ordered_warehouses AS ( SELECT wp.*, ROW_NUMBER() OVER ( PARTITION BY wp.sku_group, wp.size_label, wp.branch_code ORDER BY wp.base_priority ASC, wp.units_on_hand DESC ) AS warehouse_order FROM warehouse_preference wp ), allocation AS ( SELECT ow.marketplace_mapped, ow.sku_group, ow.size_label, ow.branch_code, ow.store_rank, ow.facility, ow.warehouse_order, ow.replen_units, ow.units_on_hand, CASE WHEN ow.units_on_hand >= ow.replen_units THEN ow.replen_units ELSE ow.units_on_hand END AS allocated_units, ow.replen_units - SUM( CASE WHEN ow.units_on_hand >= ow.replen_units THEN ow.replen_units ELSE ow.units_on_hand END ) OVER ( PARTITION BY ow.sku_group, ow.size_label, ow.branch_code ORDER BY ow.warehouse_order ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS remaining_units FROM ordered_warehouses ow ), final_allocation AS ( SELECT a.marketplace_mapped, a.sku_group, a.size_label, a.branch_code, a.store_rank, a.facility, a.warehouse_order, CASE WHEN a.remaining_units < 0 THEN a.allocated_units + a.remaining_units ELSE a.allocated_units END AS allocated_units FROM allocation a WHERE a.allocated_units > 0 ), capped_allocation AS ( SELECT f.marketplace_mapped, f.sku_group, f.size_label, f.branch_code, f.store_rank, f.facility, f.warehouse_order, f.allocated_units, SUM(f.allocated_units) OVER ( PARTITION BY f.sku_group, f.size_label, f.facility ORDER BY f.warehouse_order, f.branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_allocated, w.units_on_hand FROM final_allocation f JOIN WarehouseInfo_belts w ON w.sku_group = f.sku_group AND w.size_label = f.size_label AND w.facility = f.facility ), balanced_allocation AS ( SELECT ca.marketplace_mapped, ca.sku_group, ca.size_label, ca.branch_code, ca.store_rank, ca.facility, ca.warehouse_order, CASE WHEN ca.cum_allocated <= ca.units_on_hand THEN ca.allocated_units WHEN ca.cum_allocated - ca.allocated_units < ca.units_on_hand THEN ca.units_on_hand - (ca.cum_allocated - ca.allocated_units) ELSE 0 END AS allocated_units FROM capped_allocation ca WHERE ca.allocated_units > 0 ), store_size_current AS ( SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'S\' AS size_label, COALESCE(r.s_units, 0) AS current_units FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'M\', COALESCE(r.m_units, 0) FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'L\', COALESCE(r.l_units, 0) FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'XL\', COALESCE(r.xl_units, 0) FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'XXL\', COALESCE(r.xxl_units,0) FROM RequiredQuantities_belts r ), alloc_by_size AS ( SELECT marketplace_mapped, branch_code, sku_group, UPPER(size_label) AS size_label, SUM(allocated_units) AS allocated_units FROM balanced_allocation GROUP BY 1,2,3,4 ), eligible_skus AS ( SELECT c.marketplace_mapped, c.branch_code, c.sku_group FROM store_size_current c LEFT JOIN alloc_by_size a ON a.marketplace_mapped = c.marketplace_mapped AND a.branch_code = c.branch_code AND a.sku_group = c.sku_group AND a.size_label = c.size_label GROUP BY c.marketplace_mapped, c.branch_code, c.sku_group HAVING SUM( CASE WHEN COALESCE(c.current_units,0) + COALESCE(a.allocated_units,0) > 0 THEN 1 ELSE 0 END ) >= 4 ) SELECT CASE UPPER(ba.size_label) WHEN \'S\' THEN ba.sku_group || \'-30\' WHEN \'M\' THEN ba.sku_group || \'-32\' WHEN \'L\' THEN ba.sku_group || \'-34\' WHEN \'XL\' THEN ba.sku_group || \'-36\' WHEN \'XXL\' THEN ba.sku_group || \'-38\' ELSE ba.sku_group END AS SKU_CODE, ba.branch_code AS BRANCH_CODE, ba.store_rank AS STORE_RANK, ba.facility AS FACILITY, ba.warehouse_order AS WAREHOUSE_ORDER, ba.allocated_units AS ALLOCATED_UNITS FROM balanced_allocation ba JOIN eligible_skus e ON e.marketplace_mapped = ba.marketplace_mapped AND e.branch_code = ba.branch_code AND e.sku_group = ba.sku_group WHERE ba.allocated_units > 0 ORDER BY SKU_CODE, BRANCH_CODE, WAREHOUSE_ORDER ), shoes as ( WITH stores_perf AS ( SELECT DISTINCT marketplace_mapped, branch_code FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE marketplace_mapped NOT IN ( \'SNITCH - WH - B2B\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\', \'SNITCH - WH - RAJASTHAN\', \'SNITCH - WH - U.P\', \'SNITCH - WH - M P\', \'SNITCH - WH - GUJARAT\', \'SNITCH - WH - MAHARASTRA\' ) ), belts_list AS ( SELECT CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN REGEXP_COUNT(\"Item SkuCode\", \'-\') >= 2 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) WHEN REGEXP_COUNT(\"Item SkuCode\", \'-\') = 1 AND REGEXP_LIKE(SPLIT_PART(\"Item SkuCode\", \'-\', 2), \'^[0-9]+$\') THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END AS sku_group, FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'SH%\' GROUP BY CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN REGEXP_COUNT(\"Item SkuCode\", \'-\') >= 2 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) WHEN REGEXP_COUNT(\"Item SkuCode\", \'-\') = 1 AND REGEXP_LIKE(SPLIT_PART(\"Item SkuCode\", \'-\', 2), \'^[0-9]+$\') THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END HAVING COALESCE(SUM(inventory), 0) > 0 ), beltsxstores AS ( SELECT s.marketplace_mapped, s.branch_code, p.sku_group FROM stores_perf s CROSS JOIN belts_list p ), RequiredQuantities_belts AS ( Select * from ( SELECT a.marketplace_mapped, a.branch_code, a.sku_group, COALESCE(h.dept,8) as dept, h.FOOTWEAR AS status, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,99,101,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END AS store_rank, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END AS is_new_combination, COALESCE(b.new_category, \'Shoes\') AS new_category, SUM(COALESCE(SALES_LAST_7_DAYS, 0)) AS sale_7, SUM(COALESCE(SALES_LAST_15_DAYS, 0)) AS sale_15, SUM(COALESCE(SALES_LAST_30_DAYS, 0)) AS sale_30, SUM(COALESCE(INVENTORY, 0)) AS inventory, SUM(COALESCE(JIT_QTY, 0)) AS jit_qty, SUM(COALESCE(S_UNITS + JIT_S_UNITS, 0)) AS s_units, SUM(COALESCE(M_UNITS + JIT_M_UNITS, 0)) AS m_units, SUM(COALESCE(L_UNITS + JIT_L_UNITS, 0)) AS l_units, SUM(COALESCE(XL_UNITS + JIT_XL_UNITS, 0)) AS xl_units, SUM(COALESCE(XXL_UNITS + JIT_2XL_UNITS, 0)) AS xxl_units FROM beltsxstores a LEFT JOIN ( SELECT *, UPPER(sku_group) AS upper_sku_group FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ) b ON a.marketplace_mapped = b.marketplace_mapped AND a.branch_code = b.branch_code AND a.sku_group = b.upper_sku_group LEFT JOIN ( SELECT DISTINCT branch_code, FOOTWEAR, \"Footwear(Dept)\" AS dept FROM snitch_db.maplemonk.offline_long_tail_sheet1 ) h ON a.branch_code = h.branch_code WHERE a.branch_code IS NOT NULL AND LOWER(h.FOOTWEAR) = \'yes\' GROUP BY a.marketplace_mapped, a.branch_code, a.sku_group, h.dept, h.FOOTWEAR, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,99,101,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END, COALESCE(b.new_category, \'Shoes\') ) order by sale_7 desc ) , size_dist AS ( SELECT r.*, r.dept::int AS dept_int, d.size, d.weight, d.priority, (r.dept::int * d.weight) / 8.0 AS raw_desired, FLOOR((r.dept::int * d.weight) / 8.0) AS base_desired, ((r.dept::int * d.weight) / 8.0) - FLOOR((r.dept::int * d.weight) / 8.0) AS frac_part FROM RequiredQuantities_belts r JOIN ( SELECT \'M\' AS size, 2 AS weight, 1 AS priority UNION ALL SELECT \'L\', 2, 2 UNION ALL SELECT \'XL\',2, 3 UNION ALL SELECT \'S\', 1, 4 UNION ALL SELECT \'XXL\',1, 5 ) d ), size_dist_with_remainder AS ( SELECT sd.*, SUM(sd.base_desired) OVER ( PARTITION BY sd.marketplace_mapped, sd.branch_code, sd.sku_group ) AS sum_base, (sd.dept_int - SUM(sd.base_desired) OVER ( PARTITION BY sd.marketplace_mapped, sd.branch_code, sd.sku_group )) AS remainder, ROW_NUMBER() OVER ( PARTITION BY sd.marketplace_mapped, sd.branch_code, sd.sku_group ORDER BY sd.frac_part DESC, sd.priority ASC ) AS frac_rank FROM size_dist sd ), size_target AS ( SELECT marketplace_mapped, branch_code, sku_group, size, base_desired + CASE WHEN frac_rank <= GREATEST(remainder, 0) THEN 1 ELSE 0 END AS desired_units FROM size_dist_with_remainder ), size_with_current AS ( SELECT st.marketplace_mapped, st.branch_code, st.sku_group, st.size, st.desired_units, CASE st.size WHEN \'S\' THEN r.s_units WHEN \'M\' THEN r.m_units WHEN \'L\' THEN r.l_units WHEN \'XL\' THEN r.xl_units WHEN \'XXL\' THEN r.xxl_units END AS current_units FROM size_target st JOIN RequiredQuantities_belts r ON r.marketplace_mapped = st.marketplace_mapped AND r.branch_code = st.branch_code AND r.sku_group = st.sku_group ), size_requirements AS ( SELECT marketplace_mapped, branch_code, sku_group, UPPER(size) AS size, desired_units, current_units, GREATEST(desired_units - COALESCE(current_units, 0), 0) AS required_units FROM size_with_current ) , WarehouseInfo_belts AS ( WITH data AS ( SELECT \"Item SkuCode\" AS sku_full, FACILITY, COALESCE(SUM(inventory), 0) AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'SH0%\' GROUP BY 1,2 ), normalized AS ( SELECT sku_full, facility, qty, CASE WHEN UPPER(sku_full) LIKE \'4C%\' THEN SPLIT_PART(sku_full, \'-\', 1) || \'-\' || SPLIT_PART(sku_full, \'-\', 2) || \'-\' || SPLIT_PART(sku_full, \'-\', 3) WHEN REGEXP_COUNT(sku_full, \'-\') >= 2 THEN SPLIT_PART(sku_full, \'-\', 1) || \'-\' || SPLIT_PART(sku_full, \'-\', 2) WHEN REGEXP_COUNT(sku_full, \'-\') = 1 AND REGEXP_LIKE(SPLIT_PART(sku_full, \'-\', 2), \'^[0-9]+$\') THEN SPLIT_PART(sku_full, \'-\', 1) WHEN POSITION(\'-\' IN sku_full) > 0 THEN SPLIT_PART(sku_full, \'-\', 1) || \'-\' || SPLIT_PART(sku_full, \'-\', 2) ELSE sku_full END AS SKU_GROUP, UPPER( CASE REGEXP_SUBSTR(sku_full, \'[^-]+$\') WHEN \'40\' THEN \'S\' WHEN \'41\' THEN \'M\' WHEN \'42\' THEN \'L\' WHEN \'43\' THEN \'XL\' WHEN \'44\' THEN \'XXL\' WHEN \'45\' THEN \'XXXL\' ELSE NULL END ) AS size_label FROM data ) SELECT sku_group, size_label, facility, SUM(qty) AS units_on_hand FROM normalized WHERE size_label IS NOT NULL AND qty > 0 GROUP BY sku_group, size_label, facility ), warehouse_preference AS ( SELECT sr.marketplace_mapped, sr.branch_code, sr.sku_group, UPPER(sr.size) AS size_label, r.store_rank, sr.required_units AS replen_units, w.facility, w.units_on_hand, CASE WHEN r.store_rank = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'North\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 2 WHEN r.store_rank = \'South\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM size_requirements sr JOIN RequiredQuantities_belts r ON r.marketplace_mapped = sr.marketplace_mapped AND r.branch_code = sr.branch_code AND r.sku_group = sr.sku_group JOIN WarehouseInfo_belts w ON w.sku_group = sr.sku_group AND w.size_label = UPPER(sr.size) ), ordered_warehouses AS ( SELECT wp.*, ROW_NUMBER() OVER ( PARTITION BY wp.sku_group, wp.size_label, wp.branch_code ORDER BY wp.base_priority ASC, wp.units_on_hand DESC ) AS warehouse_order FROM warehouse_preference wp ), allocation AS ( SELECT ow.marketplace_mapped, ow.sku_group, ow.size_label, ow.branch_code, ow.store_rank, ow.facility, ow.warehouse_order, ow.replen_units, ow.units_on_hand, CASE WHEN ow.units_on_hand >= ow.replen_units THEN ow.replen_units ELSE ow.units_on_hand END AS allocated_units, ow.replen_units - SUM( CASE WHEN ow.units_on_hand >= ow.replen_units THEN ow.replen_units ELSE ow.units_on_hand END ) OVER ( PARTITION BY ow.sku_group, ow.size_label, ow.branch_code ORDER BY ow.warehouse_order ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS remaining_units FROM ordered_warehouses ow ), final_allocation AS ( SELECT a.marketplace_mapped, a.sku_group, a.size_label, a.branch_code, a.store_rank, a.facility, a.warehouse_order, CASE WHEN a.remaining_units < 0 THEN a.allocated_units + a.remaining_units ELSE a.allocated_units END AS allocated_units FROM allocation a WHERE a.allocated_units > 0 ), capped_allocation AS ( SELECT f.marketplace_mapped, f.sku_group, f.size_label, f.branch_code, f.store_rank, f.facility, f.warehouse_order, f.allocated_units, SUM(f.allocated_units) OVER ( PARTITION BY f.sku_group, f.size_label, f.facility ORDER BY f.warehouse_order, f.branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_allocated, w.units_on_hand FROM final_allocation f JOIN WarehouseInfo_belts w ON w.sku_group = f.sku_group AND w.size_label = f.size_label AND w.facility = f.facility ), balanced_allocation AS ( SELECT ca.marketplace_mapped, ca.sku_group, ca.size_label, ca.branch_code, ca.store_rank, ca.facility, ca.warehouse_order, CASE WHEN ca.cum_allocated <= ca.units_on_hand THEN ca.allocated_units WHEN ca.cum_allocated - ca.allocated_units < ca.units_on_hand THEN ca.units_on_hand - (ca.cum_allocated - ca.allocated_units) ELSE 0 END AS allocated_units FROM capped_allocation ca WHERE ca.allocated_units > 0 ), store_size_current AS ( SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'S\' AS size_label, COALESCE(r.s_units, 0) AS current_units FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'M\' , COALESCE(r.m_units, 0) FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'L\' , COALESCE(r.l_units, 0) FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'XL\' , COALESCE(r.xl_units, 0) FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'XXL\' , COALESCE(r.xxl_units,0) FROM RequiredQuantities_belts r ), alloc_by_size AS ( SELECT marketplace_mapped, branch_code, sku_group, UPPER(size_label) AS size_label, SUM(allocated_units) AS allocated_units FROM balanced_allocation WHERE UPPER(size_label) IN (\'S\',\'M\',\'L\',\'XL\',\'XXL\') GROUP BY 1,2,3,4 ), eligible_skus AS ( SELECT c.marketplace_mapped, c.branch_code, c.sku_group FROM store_size_current c LEFT JOIN alloc_by_size a ON a.marketplace_mapped = c.marketplace_mapped AND a.branch_code = c.branch_code AND a.sku_group = c.sku_group AND a.size_label = c.size_label WHERE UPPER(c.size_label) IN (\'S\',\'M\',\'L\',\'XL\',\'XXL\') GROUP BY c.marketplace_mapped, c.branch_code, c.sku_group HAVING SUM( CASE WHEN COALESCE(c.current_units,0) + COALESCE(a.allocated_units,0) > 0 THEN 1 ELSE 0 END ) >= 4 ) SELECT CASE UPPER(ba.size_label) WHEN \'S\' THEN ba.sku_group || \'-40\' WHEN \'M\' THEN ba.sku_group || \'-41\' WHEN \'L\' THEN ba.sku_group || \'-42\' WHEN \'XL\' THEN ba.sku_group || \'-43\' WHEN \'XXL\' THEN ba.sku_group || \'-44\' WHEN \'XXXL\' THEN ba.sku_group || \'-45\' ELSE ba.sku_group END AS SKU_CODE, ba.branch_code AS BRANCH_CODE, ba.store_rank AS STORE_RANK, ba.facility AS FACILITY, ba.warehouse_order AS WAREHOUSE_ORDER, ba.allocated_units AS ALLOCATED_UNITS FROM balanced_allocation ba JOIN eligible_skus e ON e.marketplace_mapped = ba.marketplace_mapped AND e.branch_code = ba.branch_code AND e.sku_group = ba.sku_group WHERE ba.allocated_units > 0 ORDER BY SKU_CODE, BRANCH_CODE, WAREHOUSE_ORDER ) Select *, \'Perfums\' as Category from perfumes union all select *,\'Sunglasses\' as Category from sunglasses union all select *,\'Bags\' as Category from Bagss union all select *,\'Belts\' as Category from Belts union all Select *,\'Shoes\' as Category From Shoes ; ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE or REPLACE table snitch_db.maplemonk.offline_long_tail_Replen_7_26 as WITH SHOES AS ( WITH store_sku_inventory AS ( SELECT *, COUNT(DISTINCT sku_group) OVER ( PARTITION BY branch_code, branch_name ) AS option_count FROM ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS branch_name, UPPER(TRIM(sku_group)) AS sku_group, SUM(COALESCE(inventory, 0)) AS inventory_qty, SUM(COALESCE(jit_qty, 0)) AS jit_qty, SUM(COALESCE(inventory, 0)) + SUM(COALESCE(jit_qty, 0)) AS stock_qty, SUM(COALESCE(xs_units, 0)) AS size_40, SUM(COALESCE(s_units, 0)) AS size_41, SUM(COALESCE(m_units, 0)) AS size_42, SUM(COALESCE(l_units, 0)) AS size_43, SUM(COALESCE(xl_units, 0)) AS size_44, SUM(COALESCE(xxl_units, 0)) AS size_45, SUM(COALESCE(xl3_units, 0)) AS size_46, SUM(COALESCE(jit_xs_units, 0)) AS jit_40, SUM(COALESCE(jit_s_units, 0)) AS jit_41, SUM(COALESCE(jit_m_units, 0)) AS jit_42, SUM(COALESCE(jit_l_units, 0)) AS jit_43, SUM(COALESCE(jit_xl_units, 0)) AS jit_44, SUM(COALESCE(jit_2xl_units, 0)) AS jit_45, SUM(COALESCE(jit_3xl_units, 0)) AS jit_46, SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) AS available_40, SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) AS available_41, SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) AS available_42, SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) AS available_43, CASE WHEN SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) > 0 AND SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) > 0 AND SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) > 0 AND SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) > 0 THEN \'FULL_SIZE\' ELSE \'CUT_SIZE\' END AS size_status, CASE WHEN SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) > 0 AND SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) > 0 AND SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) > 0 AND SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) > 0 THEN \'FULL SIZE\' ELSE RTRIM( CASE WHEN SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) <= 0 THEN \'40 , \' ELSE \'\' END || CASE WHEN SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) <= 0 THEN \'41 , \' ELSE \'\' END || CASE WHEN SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) <= 0 THEN \'42 , \' ELSE \'\' END || CASE WHEN SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) <= 0 THEN \'43 , \' ELSE \'\' END, \', \' ) END AS size_remark, SUM(COALESCE(sales_last_30_days, 0)) AS sales_last_30_days, SUM(COALESCE(sales_last_15_days, 0)) AS sales_last_15_days, SUM(COALESCE(sales_last_7_days, 0)) AS sales_last_7_days, ( 0.6 * (SUM(COALESCE(sales_last_7_days, 0)) / 7.0) + 0.3 * (SUM(COALESCE(sales_last_15_days, 0)) / 15.0) + 0.1 * (SUM(COALESCE(sales_last_30_days, 0)) / 30.0) ) AS ros, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( SUM(COALESCE(sales_last_30_days, 0)) + SUM(COALESCE(inventory, 0)), 0 ) AS str FROM snitch_db.maplemonk.offline_master WHERE UPPER(TRIM(sku_group)) LIKE \'SH0%\' AND COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 GROUP BY branch_code, UPPER(TRIM(marketplace_mapped)), UPPER(TRIM(sku_group)) ) ), stores_perf AS ( SELECT DISTINCT branch_code, branch_name AS marketplace_mapped FROM store_sku_inventory ), store_option_count AS ( SELECT branch_code, branch_name AS marketplace_mapped, MAX(option_count) AS option_count FROM store_sku_inventory GROUP BY 1, 2 ), store_region AS ( SELECT DISTINCT branch_code, UPPER(TRIM(zone)) AS region FROM snitch_db.maplemonk.store_category_delta ), schedule_rpl AS ( SELECT branch_code, UPPER(LEFT( CASE WHEN UPPER(cluster) IN (\'BANGALORE\', \'KARNATAKA\') AND UPPER(LEFT(south_rpl, 3)) = \'WED\' THEN \'TUE\' WHEN zone = \'South\' THEN south_rpl ELSE north_rpl END, 3 )) AS rpl_order_day FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY branch_code) AS rn FROM snitch_db.maplemonk.store_category_delta ) t WHERE rn = 1 QUALIFY ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY rpl_order_day) = 1 ), store_sell_through AS ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS marketplace_mapped, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( (SUM(COALESCE(opening_inventory, 0)) + SUM(COALESCE(inventory, 0))) / 2.0, 0 ) AS sell_through FROM snitch_db.maplemonk.off_master_htmlbase WHERE UPPER(TRIM(sku_group)) LIKE \'SH0%\' GROUP BY 1, 2 ), store_ideal_options AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(\"Footwear(Options)\" AS INT), 0) AS ideal_options FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_size AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(REPLACE(sqft, \',\', \'\') AS INT), 0) AS store_size FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_priority AS ( SELECT s.branch_code, s.marketplace_mapped, COALESCE(sr.region, \'UNKNOWN\') AS region, COALESCE(st.sell_through, 0) AS sell_through, COALESCE(io.ideal_options, 0) AS ideal_options, COALESCE(oc.option_count, 0) AS current_options, COALESCE(io.ideal_options, 0) - COALESCE(oc.option_count, 0) AS option_gap, COALESCE(sz.store_size, 0) AS store_size FROM stores_perf s LEFT JOIN store_region sr ON sr.branch_code = s.branch_code LEFT JOIN store_sell_through st ON st.branch_code = s.branch_code AND st.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_option_count oc ON oc.branch_code = s.branch_code AND oc.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_ideal_options io ON io.branch_code = s.branch_code LEFT JOIN store_size sz ON sz.branch_code = s.branch_code INNER JOIN schedule_rpl sch ON sch.branch_code = s.branch_code AND UPPER(TRIM(sch.rpl_order_day)) = UPPER(DAYNAME(CURRENT_DATE)) ), excluded_shoe_sku_groups AS ( SELECT column1 AS sku_group FROM VALUES (\'SH0120-02\'),(\'SH0039-02\'),(\'SH0131-01\'),(\'SH0144-02\'),(\'SH0120-01\'),(\'SH0114-01\'),(\'SH0120-03\'),(\'SH0039-01\'),(\'SH0137-02\'),(\'SH0136-01\'),(\'SH0136-02\'),(\'SH0136-03\'),(\'SH0131-02\'),(\'SH0145-02\'),(\'SH0137-01\'),(\'SH0134-01\'),(\'SH0145-01\'),(\'SH0119-01\'),(\'SH0144-01\'),(\'SH0119-02\'), (\'SH0134-02\'),(\'SH0119-03\'),(\'SH0139-01\'),(\'SH0121-01\'),(\'SH0121-02\'),(\'SH0132-01\'),(\'SH0121-03\'),(\'SH0133-01\'),(\'SH0128-02\'),(\'SH0124-02\'),(\'SH0124-01\'),(\'SH0149-03\'),(\'SH0126-01\'),(\'SH0149-01\'),(\'SH0132-02\'),(\'SH0127-02\'),(\'SH0130-02\'),(\'SH0115-01\'),(\'SH0130-01\'),(\'SH0127-01\'), (\'SH0122-01\'),(\'SH0129-01\'),(\'SH0128-01\'),(\'SH0126-02\'),(\'SH0122-02\'),(\'SH0143-02\'),(\'SH0133-02\'),(\'SH0129-02\'),(\'SH0143-01\'),(\'SH0122-03\'), (\'SH0149-02\'),(\'SH0135-01\'),(\'SH0038-01\'),(\'SH0042-01\'),(\'SH0040-01\'),(\'SH0041-01\'),(\'SH0148-03\'),(\'SH0151-01\'),(\'SH0108-01\'),(\'SH0113-01\'), (\'SH0111-01\'),(\'SH0140-02\'),(\'SH0113-02\'),(\'SH0109-01\'),(\'SH0142-01\'),(\'SH0110-02\'),(\'SH0154-01\'),(\'SH0125-02\'),(\'SH0123-01\'),(\'SH0140-01\'), (\'SH0112-01\'),(\'SH0150-02\'),(\'SH0116-02\'),(\'SH0148-02\'),(\'SH0141-01\'),(\'SH0154-03\'),(\'SH0141-02\'),(\'SH0117-01\'),(\'SH0152-01\'),(\'SH0116-01\'), (\'SH0147-02\'),(\'SH0108-02\'),(\'SH0125-03\'),(\'SH0109-02\'),(\'SH0147-01\'),(\'SH0150-01\'),(\'SH0142-02\'),(\'SH0146-01\'),(\'SH0151-02\'),(\'SH0110-01\'),(\'SH0123-02\'),(\'SH0113-03\'),(\'SH0148-01\'),(\'SH0125-01\'),(\'SH0138-01\'),(\'SH0001\'),(\'SH0002\'),(\'SH0003\'),(\'SH0004\'),(\'SH0005\'),(\'SH0006\'),(\'SH0007\'),(\'SH0008\'),(\'SH0009\'),(\'SH0010\'), (\'SH0011\'),(\'SH0012\'),(\'SH0013\'),(\'SH0015\'),(\'SH0016\'),(\'SH0017\'),(\'SH0018\'),(\'SH0019\'),(\'SH0020\'),(\'SH0021\'),(\'SH0022\'),(\'SH0023\'),(\'SH0024\'),(\'SH0025\'),(\'SH0026\'),(\'SH0027\'),(\'SH0028\'),(\'SH0029\'),(\'SH0030\'),(\'SH0031\'),(\'SH0032\'),(\'SH0033\'),(\'SH0034\'),(\'SH0035\'),(\'SH0036\'),(\'SH0037\'),(\'SH0118-02\'),(\'SH0038-02\'),(\'SH0029G\'),(\'SH0028W\'),(\'SH0028B\'),(\'SH0154-02\'),(\'SH0029B\'), (\'SH0038-03\'),(\'SH0118-01\'),(\'SH0184-05\'),(\'SH194-01\'),(\'SH0182-01\') ), wh_raw AS ( SELECT facility, UPPER(TRIM(\"Item SkuCode\")) AS size_sku_code, UPPER(TRIM(SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2))) AS sku_group, SPLIT_PART(\"Item SkuCode\", \'-\', 3) AS shoe_size, COALESCE(inventory, 0) AS inventory FROM snitch_db.maplemonk.unicommerce_live_inventory WHERE facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') AND UPPER(TRIM(\"Item SkuCode\")) LIKE \'SH0%\' AND SPLIT_PART(\"Item SkuCode\", \'-\', 3) IN (\'40\', \'41\', \'42\', \'43\') AND INVENTORY > 2 ), shoes_wh_size_inventory AS ( SELECT facility, CASE WHEN facility IN (\'SAPL-WH2\', \'SAPL-WH1\') THEN \'SOUTH_WH\' WHEN facility = \'SAPL-NORTH-TAURU\' THEN \'NORTH_WH\' ELSE \'OTHER_WH\' END AS wh_group, CASE WHEN facility = \'SAPL-WH2\' THEN 1 WHEN facility = \'SAPL-WH1\' THEN 2 WHEN facility = \'SAPL-NORTH-TAURU\' THEN 3 ELSE 9 END AS facility_order, sku_group, shoe_size, size_sku_code, SUM(inventory) AS wh_size_inventory FROM wh_raw WHERE sku_group NOT IN ( SELECT sku_group FROM excluded_shoe_sku_groups ) GROUP BY facility, sku_group, shoe_size, size_sku_code HAVING SUM(inventory) > 0 ), store_size_inventory_unpivot AS ( SELECT branch_code, branch_name, sku_group, \'40\' AS shoe_size, size_40 AS physical_size_qty, jit_40 AS jit_size_qty, available_40 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'41\' AS shoe_size, size_41 AS physical_size_qty, jit_41 AS jit_size_qty, available_41 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'42\' AS shoe_size, size_42 AS physical_size_qty, jit_42 AS jit_size_qty, available_42 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'43\' AS shoe_size, size_43 AS physical_size_qty, jit_43 AS jit_size_qty, available_43 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory ), replen_demand AS ( SELECT s.branch_code, s.branch_name, s.sku_group, s.shoe_size, s.physical_size_qty, s.jit_size_qty, s.current_size_available, s.inventory_qty, s.jit_qty, s.stock_qty, s.size_status, s.size_remark, s.option_count, s.sales_last_30_days, s.sales_last_15_days, s.sales_last_7_days, s.ros, s.str, CEIL(s.ros * 10) AS target_10_day_cover, GREATEST( CEIL(s.ros * 10) - COALESCE(s.current_size_available, 0),0 ) AS need_qty, CASE WHEN s.size_status = \'CUT_SIZE\' AND COALESCE(s.current_size_available, 0) <= 0 THEN 1 WHEN s.size_status = \'CUT_SIZE\' THEN 2 WHEN s.size_status = \'FULL_SIZE\' THEN 3 ELSE 4 END AS replen_priority_bucket, CASE WHEN s.size_status = \'CUT_SIZE\' AND COALESCE(s.current_size_available, 0) <= 0 THEN \'CUT_SIZE_MISSING_SIZE\' WHEN s.size_status = \'CUT_SIZE\' THEN \'CUT_SIZE_TOPUP\' WHEN s.size_status = \'FULL_SIZE\' THEN \'FULL_SIZE_ROS_TOPUP\' ELSE \'OTHER\' END AS replen_priority_reason, sp.region, sp.sell_through, sp.ideal_options, sp.current_options, sp.option_gap, sp.store_size, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'NORTH_WH\' ELSE \'SOUTH_WH\' END AS preferred_wh_group, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'SOUTH_WH\' ELSE \'NORTH_WH\' END AS fallback_wh_group FROM store_size_inventory_unpivot s LEFT JOIN store_priority sp ON sp.branch_code = s.branch_code AND sp.marketplace_mapped = s.branch_name WHERE s.shoe_size IN (\'40\', \'41\', \'42\', \'43\') AND CEIL(s.ros * 10) > COALESCE(s.current_size_available, 0) AND s.sku_group NOT IN ( SELECT sku_group FROM excluded_shoe_sku_groups ) ), wh_group_stock AS ( SELECT sku_group, shoe_size, wh_group, SUM(wh_size_inventory) AS group_stock FROM shoes_wh_size_inventory GROUP BY 1, 2, 3 ), stage_1_demand_ranked AS ( SELECT d.*, SUM(need_qty) OVER ( PARTITION BY sku_group, shoe_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_pref, SUM(need_qty) OVER ( PARTITION BY sku_group, shoe_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_pref_before FROM replen_demand d ), stage_1_group_alloc AS ( SELECT d.*, COALESCE(w.group_stock, 0) AS preferred_group_stock, GREATEST(LEAST(d.cum_need_pref, COALESCE(w.group_stock, 0)) - COALESCE(d.cum_need_pref_before, 0),0) AS pref_alloc_qty FROM stage_1_demand_ranked d LEFT JOIN wh_group_stock w ON w.sku_group = d.sku_group AND w.shoe_size = d.shoe_size AND w.wh_group = d.preferred_wh_group ), stage_1_alloc_ranked_for_facility AS ( SELECT *, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, shoe_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_pref_alloc, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, shoe_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_pref_alloc_before FROM stage_1_group_alloc WHERE pref_alloc_qty > 0 ), stage_1_facility_stock_ranked AS ( SELECT *, SUM(wh_size_inventory) OVER ( PARTITION BY sku_group, shoe_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fac_stock, SUM(wh_size_inventory) OVER ( PARTITION BY sku_group, shoe_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fac_stock_before FROM shoes_wh_size_inventory ), stage_1_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, d.shoe_size, w.size_sku_code, w.facility, w.wh_group, \'PREFERRED_WH\' AS allocation_stage, d.physical_size_qty, d.jit_size_qty, d.current_size_available, d.inventory_qty, d.jit_qty, d.stock_qty, d.size_status, d.size_remark, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_10_day_cover, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_size_inventory AS warehouse_size_stock, GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_1_alloc_ranked_for_facility d JOIN stage_1_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.shoe_size = d.shoe_size AND w.wh_group = d.preferred_wh_group WHERE GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) > 0 ), stage_1_facility_consumed AS ( SELECT sku_group, shoe_size, facility, SUM(allocated_qty) AS consumed_qty FROM stage_1_facility_alloc GROUP BY 1, 2, 3 ), facility_stock_after_stage_1 AS ( SELECT w.sku_group, w.shoe_size, w.size_sku_code, w.facility, w.wh_group, w.facility_order, w.wh_size_inventory, COALESCE(c.consumed_qty, 0) AS consumed_stage_1_qty, GREATEST(w.wh_size_inventory - COALESCE(c.consumed_qty, 0), 0) AS remaining_facility_stock FROM shoes_wh_size_inventory w LEFT JOIN stage_1_facility_consumed c ON c.sku_group = w.sku_group AND c.shoe_size = w.shoe_size AND c.facility = w.facility ), stage_2_remaining_demand AS ( SELECT *, GREATEST(need_qty - pref_alloc_qty, 0) AS remaining_need_qty FROM stage_1_group_alloc WHERE GREATEST(need_qty - pref_alloc_qty, 0) > 0 ), stage_2_wh_group_stock AS ( SELECT sku_group, shoe_size, wh_group, SUM(remaining_facility_stock) AS remaining_group_stock FROM facility_stock_after_stage_1 GROUP BY 1, 2, 3 ), stage_2_demand_ranked AS ( SELECT d.*, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, shoe_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_fallback, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, shoe_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_fallback_before FROM stage_2_remaining_demand d ), stage_2_group_alloc AS ( SELECT d.*, COALESCE(w.remaining_group_stock, 0) AS fallback_group_stock, GREATEST( LEAST(d.cum_need_fallback, COALESCE(w.remaining_group_stock, 0)) - COALESCE(d.cum_need_fallback_before, 0), 0 ) AS fallback_alloc_qty FROM stage_2_demand_ranked d LEFT JOIN stage_2_wh_group_stock w ON w.sku_group = d.sku_group AND w.shoe_size = d.shoe_size AND w.wh_group = d.fallback_wh_group ), stage_2_alloc_ranked_for_facility AS ( SELECT *, SUM(fallback_alloc_qty) OVER ( PARTITION BY sku_group, shoe_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fallback_alloc, SUM(fallback_alloc_qty) OVER ( PARTITION BY sku_group, shoe_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fallback_alloc_before FROM stage_2_group_alloc WHERE fallback_alloc_qty > 0 ), stage_2_facility_stock_ranked AS ( SELECT *, SUM(remaining_facility_stock) OVER ( PARTITION BY sku_group, shoe_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_remaining_fac_stock, SUM(remaining_facility_stock) OVER ( PARTITION BY sku_group, shoe_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_remaining_fac_stock_before FROM facility_stock_after_stage_1 WHERE remaining_facility_stock > 0 ), stage_2_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, d.shoe_size, w.size_sku_code, w.facility, w.wh_group, \'FALLBACK_WH\' AS allocation_stage, d.physical_size_qty, d.jit_size_qty, d.current_size_available, d.inventory_qty, d.jit_qty, d.stock_qty, d.size_status, d.size_remark, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_10_day_cover, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_size_inventory AS warehouse_size_stock, GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_2_alloc_ranked_for_facility d JOIN stage_2_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.shoe_size = d.shoe_size AND w.wh_group = d.fallback_wh_group WHERE GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) > 0 ), final_allocation AS ( SELECT * FROM stage_1_facility_alloc UNION ALL SELECT * FROM stage_2_facility_alloc ) SELECT branch_code, branch_name, region, sku_group, shoe_size, size_sku_code, facility AS warehouse_name, wh_group, allocation_stage, physical_size_qty, jit_size_qty, current_size_available, target_10_day_cover, need_qty, allocated_qty, warehouse_size_stock, inventory_qty AS store_inventory_qty, jit_qty AS store_jit_qty, stock_qty AS store_stock_jit_qty, size_status, size_remark, replen_priority_bucket, replen_priority_reason, option_count, ideal_options, current_options, option_gap, store_size, sales_last_7_days, sales_last_15_days, sales_last_30_days, ROUND(ros, 4) AS ros, ROUND(str, 4) AS str, ROUND(sell_through, 4) AS store_sell_through, preferred_wh_group, fallback_wh_group FROM final_allocation WHERE allocated_qty > 0 ORDER BY replen_priority_bucket ASC, sku_group, shoe_size, CASE WHEN allocation_stage = \'PREFERRED_WH\' THEN 1 ELSE 2 END, store_sell_through DESC, option_gap DESC, store_size DESC, ros DESC, branch_code, warehouse_name ), BELTS AS ( WITH store_sku_inventory AS ( SELECT *, COUNT(DISTINCT sku_group) OVER ( PARTITION BY branch_code, branch_name ) AS option_count FROM ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS branch_name, UPPER(TRIM(sku_group)) AS sku_group, SUM(COALESCE(inventory, 0)) AS inventory_qty, SUM(COALESCE(jit_qty, 0)) AS jit_qty, SUM(COALESCE(inventory, 0)) + SUM(COALESCE(jit_qty, 0)) AS stock_qty, SUM(COALESCE(xs_units, 0)) AS size_28, SUM(COALESCE(s_units, 0)) AS size_30, SUM(COALESCE(m_units, 0)) AS size_32, SUM(COALESCE(l_units, 0)) AS size_34, SUM(COALESCE(xl_units, 0)) AS size_36, SUM(COALESCE(xxl_units, 0)) AS size_38, SUM(COALESCE(xl3_units, 0)) AS size_40, SUM(COALESCE(jit_xs_units, 0)) AS jit_28, SUM(COALESCE(jit_s_units, 0)) AS jit_30, SUM(COALESCE(jit_m_units, 0)) AS jit_32, SUM(COALESCE(jit_l_units, 0)) AS jit_34, SUM(COALESCE(jit_xl_units, 0)) AS jit_36, SUM(COALESCE(jit_2xl_units, 0)) AS jit_38, SUM(COALESCE(jit_3xl_units, 0)) AS jit_40, SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) AS available_28, SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) AS available_30, SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) AS available_32, SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) AS available_34, SUM(COALESCE(xl_units, 0)) + SUM(COALESCE(jit_xl_units, 0)) AS available_36, SUM(COALESCE(xxl_units, 0)) + SUM(COALESCE(jit_2xl_units, 0)) AS available_38, SUM(COALESCE(xl3_units, 0)) + SUM(COALESCE(jit_3xl_units, 0)) AS available_40, CASE WHEN UPPER(TRIM(sku_group)) LIKE \'4MBL%\' AND ( CASE WHEN SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xl_units, 0)) + SUM(COALESCE(jit_xl_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xl3_units, 0)) + SUM(COALESCE(jit_3xl_units, 0)) > 0 THEN 1 ELSE 0 END ) < 3 AND ( CASE WHEN SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xl_units, 0)) + SUM(COALESCE(jit_xl_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xxl_units, 0)) + SUM(COALESCE(jit_2xl_units, 0)) > 0 THEN 1 ELSE 0 END ) < 4 THEN \'CUT_SIZE\' ELSE \'FULL_SIZE\' END AS size_status, CASE WHEN NOT ( UPPER(TRIM(sku_group)) LIKE \'4MBL%\' AND ( CASE WHEN SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xl_units, 0)) + SUM(COALESCE(jit_xl_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xl3_units, 0)) + SUM(COALESCE(jit_3xl_units, 0)) > 0 THEN 1 ELSE 0 END ) < 3 AND ( CASE WHEN SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xl_units, 0)) + SUM(COALESCE(jit_xl_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xxl_units, 0)) + SUM(COALESCE(jit_2xl_units, 0)) > 0 THEN 1 ELSE 0 END ) < 4 ) THEN \'FULL SIZE\' ELSE RTRIM( CASE WHEN SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) <= 0 THEN \'32 , \' ELSE \'\' END || CASE WHEN SUM(COALESCE(xl_units, 0)) + SUM(COALESCE(jit_xl_units, 0)) <= 0 THEN \'36 , \' ELSE \'\' END || CASE WHEN SUM(COALESCE(xl3_units, 0)) + SUM(COALESCE(jit_3xl_units, 0)) <= 0 THEN \'40 , \' ELSE \'\' END, \', \' ) END AS size_remark, SUM(COALESCE(sales_last_30_days, 0)) AS sales_last_30_days, SUM(COALESCE(sales_last_15_days, 0)) AS sales_last_15_days, SUM(COALESCE(sales_last_7_days, 0)) AS sales_last_7_days, ( 0.5 * (SUM(COALESCE(sales_last_7_days, 0)) / 7.0) + 0.3 * (SUM(COALESCE(sales_last_15_days, 0)) / 15.0) + 0.2 * (SUM(COALESCE(sales_last_30_days, 0)) / 30.0) ) AS ros, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( SUM(COALESCE(sales_last_30_days, 0)) + SUM(COALESCE(inventory, 0)), 0 ) AS str FROM snitch_db.maplemonk.offline_master WHERE UPPER(TRIM(sku_group)) LIKE \'4MBL%\' AND COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 GROUP BY branch_code, UPPER(TRIM(marketplace_mapped)), UPPER(TRIM(sku_group)) ) ), stores_perf AS ( SELECT DISTINCT branch_code, branch_name AS marketplace_mapped FROM store_sku_inventory ), store_option_count AS ( SELECT branch_code, branch_name AS marketplace_mapped, MAX(option_count) AS option_count FROM store_sku_inventory GROUP BY 1, 2 ), store_region AS ( SELECT DISTINCT branch_code, UPPER(TRIM(zone)) AS region FROM snitch_db.maplemonk.store_category_delta ), schedule_rpl AS ( SELECT branch_code, UPPER(LEFT( CASE WHEN UPPER(cluster) IN (\'BANGALORE\', \'KARNATAKA\') AND UPPER(LEFT(south_rpl, 3)) = \'WED\' THEN \'TUE\' WHEN zone = \'South\' THEN south_rpl ELSE north_rpl END, 3 )) AS rpl_order_day FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY branch_code) AS rn FROM snitch_db.maplemonk.store_category_delta ) t WHERE rn = 1 QUALIFY ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY rpl_order_day) = 1 ), store_sell_through AS ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS marketplace_mapped, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( (SUM(COALESCE(opening_inventory, 0)) + SUM(COALESCE(inventory, 0))) / 2.0, 0 ) AS sell_through FROM snitch_db.maplemonk.off_master_htmlbase WHERE UPPER(TRIM(sku_group)) LIKE \'4MBL%\' GROUP BY 1, 2 ), store_ideal_options AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(\"Belts(Options)\" AS INT), 0) AS ideal_options FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_size AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(REPLACE(sqft, \',\', \'\') AS INT), 0) AS store_size FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_priority AS ( SELECT s.branch_code, s.marketplace_mapped, COALESCE(sr.region, \'UNKNOWN\') AS region, COALESCE(st.sell_through, 0) AS sell_through, COALESCE(io.ideal_options, 0) AS ideal_options, COALESCE(oc.option_count, 0) AS current_options, COALESCE(io.ideal_options, 0) - COALESCE(oc.option_count, 0) AS option_gap, COALESCE(sz.store_size, 0) AS store_size FROM stores_perf s LEFT JOIN store_region sr ON sr.branch_code = s.branch_code LEFT JOIN store_sell_through st ON st.branch_code = s.branch_code AND st.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_option_count oc ON oc.branch_code = s.branch_code AND oc.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_ideal_options io ON io.branch_code = s.branch_code LEFT JOIN store_size sz ON sz.branch_code = s.branch_code INNER JOIN schedule_rpl sch ON sch.branch_code = s.branch_code AND UPPER(TRIM(sch.rpl_order_day)) = UPPER(DAYNAME(CURRENT_DATE)) ), wh_raw AS ( SELECT facility, UPPER(TRIM(\"Item SkuCode\")) AS size_sku_code, UPPER(TRIM(SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2))) AS sku_group, SPLIT_PART(\"Item SkuCode\", \'-\', 3) AS belt_size, COALESCE(inventory, 0) AS inventory FROM snitch_db.maplemonk.unicommerce_live_inventory WHERE facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') AND UPPER(TRIM(\"Item SkuCode\")) LIKE \'4MBL%\' AND SPLIT_PART(\"Item SkuCode\", \'-\', 3) IN (\'28\',\'30\',\'32\',\'34\', \'36\',\'38\', \'40\') AND INVENTORY > 2 ), belts_wh_size_inventory AS ( SELECT facility, CASE WHEN facility IN (\'SAPL-WH2\', \'SAPL-WH1\') THEN \'SOUTH_WH\' WHEN facility = \'SAPL-NORTH-TAURU\' THEN \'NORTH_WH\' ELSE \'OTHER_WH\' END AS wh_group, CASE WHEN facility = \'SAPL-WH2\' THEN 1 WHEN facility = \'SAPL-WH1\' THEN 2 WHEN facility = \'SAPL-NORTH-TAURU\' THEN 3 ELSE 9 END AS facility_order, sku_group, belt_size, size_sku_code, SUM(inventory) AS wh_size_inventory FROM wh_raw GROUP BY facility, sku_group, belt_size, size_sku_code HAVING SUM(inventory) > 0 ), store_size_inventory_unpivot AS ( SELECT branch_code, branch_name, sku_group, \'28\' AS belt_size, size_28 AS physical_size_qty, jit_28 AS jit_size_qty, available_28 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'30\' AS belt_size, size_30 AS physical_size_qty, jit_30 AS jit_size_qty, available_30 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'32\' AS belt_size, size_32 AS physical_size_qty, jit_32 AS jit_size_qty, available_32 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'34\' AS belt_size, size_34 AS physical_size_qty, jit_34 AS jit_size_qty, available_34 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'36\' AS belt_size, size_36 AS physical_size_qty, jit_36 AS jit_size_qty, available_36 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'38\' AS belt_size, size_38 AS physical_size_qty, jit_38 AS jit_size_qty, available_38 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'40\' AS belt_size, size_40 AS physical_size_qty, jit_40 AS jit_size_qty, available_40 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory ), replen_demand AS ( SELECT s.branch_code, s.branch_name, s.sku_group, s.belt_size, s.physical_size_qty, s.jit_size_qty, s.current_size_available, s.inventory_qty, s.jit_qty, s.stock_qty, s.size_status, s.size_remark, s.option_count, s.sales_last_30_days, s.sales_last_15_days, s.sales_last_7_days, s.ros, s.str, CEIL(s.ros * 10) AS target_10_day_cover, GREATEST(CEIL(s.ros * 10) - COALESCE(s.current_size_available, 0), 0) AS need_qty, CASE WHEN s.size_status = \'CUT_SIZE\' AND COALESCE(s.current_size_available, 0) <= 0 THEN 1 WHEN s.size_status = \'CUT_SIZE\' THEN 2 WHEN s.size_status = \'FULL_SIZE\' THEN 3 ELSE 4 END AS replen_priority_bucket, CASE WHEN s.size_status = \'CUT_SIZE\' AND COALESCE(s.current_size_available, 0) <= 0 THEN \'CUT_SIZE_MISSING_SIZE\' WHEN s.size_status = \'CUT_SIZE\' THEN \'CUT_SIZE_TOPUP\' WHEN s.size_status = \'FULL_SIZE\' THEN \'FULL_SIZE_ROS_TOPUP\' ELSE \'OTHER\' END AS replen_priority_reason, sp.region, sp.sell_through, sp.ideal_options, sp.current_options, sp.option_gap, sp.store_size, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'NORTH_WH\' ELSE \'SOUTH_WH\' END AS preferred_wh_group, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'SOUTH_WH\' ELSE \'NORTH_WH\' END AS fallback_wh_group FROM store_size_inventory_unpivot s LEFT JOIN store_priority sp ON sp.branch_code = s.branch_code AND sp.marketplace_mapped = s.branch_name WHERE s.belt_size IN (\'28\', \'30\', \'32\', \'34\', \'36\', \'38\', \'40\') AND COALESCE(s.current_size_available, 0) > 0 AND CEIL(s.ros * 10) > COALESCE(s.current_size_available, 0) ), wh_group_stock AS ( SELECT sku_group, belt_size, wh_group, SUM(wh_size_inventory) AS group_stock FROM belts_wh_size_inventory GROUP BY 1, 2, 3 ), stage_1_demand_ranked AS ( SELECT d.*, SUM(need_qty) OVER ( PARTITION BY sku_group, belt_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_pref, SUM(need_qty) OVER ( PARTITION BY sku_group, belt_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_pref_before FROM replen_demand d ), stage_1_group_alloc AS ( SELECT d.*, COALESCE(w.group_stock, 0) AS preferred_group_stock, GREATEST( LEAST(d.cum_need_pref, COALESCE(w.group_stock, 0)) - COALESCE(d.cum_need_pref_before, 0), 0 ) AS pref_alloc_qty FROM stage_1_demand_ranked d LEFT JOIN wh_group_stock w ON w.sku_group = d.sku_group AND w.belt_size = d.belt_size AND w.wh_group = d.preferred_wh_group ), stage_1_alloc_ranked_for_facility AS ( SELECT *, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, belt_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_pref_alloc, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, belt_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_pref_alloc_before FROM stage_1_group_alloc WHERE pref_alloc_qty > 0 ), stage_1_facility_stock_ranked AS ( SELECT *, SUM(wh_size_inventory) OVER ( PARTITION BY sku_group, belt_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fac_stock, SUM(wh_size_inventory) OVER ( PARTITION BY sku_group, belt_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fac_stock_before FROM belts_wh_size_inventory ), stage_1_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, d.belt_size, w.size_sku_code, w.facility, w.wh_group, \'PREFERRED_WH\' AS allocation_stage, d.physical_size_qty, d.jit_size_qty, d.current_size_available, d.inventory_qty, d.jit_qty, d.stock_qty, d.size_status, d.size_remark, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_10_day_cover, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_size_inventory AS warehouse_size_stock, GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_1_alloc_ranked_for_facility d JOIN stage_1_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.belt_size = d.belt_size AND w.wh_group = d.preferred_wh_group WHERE GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) > 0 ), stage_1_facility_consumed AS ( SELECT sku_group, belt_size, facility, SUM(allocated_qty) AS consumed_qty FROM stage_1_facility_alloc GROUP BY 1, 2, 3 ), facility_stock_after_stage_1 AS ( SELECT w.sku_group, w.belt_size, w.size_sku_code, w.facility, w.wh_group, w.facility_order, w.wh_size_inventory, COALESCE(c.consumed_qty, 0) AS consumed_stage_1_qty, GREATEST(w.wh_size_inventory - COALESCE(c.consumed_qty, 0), 0) AS remaining_facility_stock FROM belts_wh_size_inventory w LEFT JOIN stage_1_facility_consumed c ON c.sku_group = w.sku_group AND c.belt_size = w.belt_size AND c.facility = w.facility ), stage_2_remaining_demand AS ( SELECT *, GREATEST(need_qty - pref_alloc_qty, 0) AS remaining_need_qty FROM stage_1_group_alloc WHERE GREATEST(need_qty - pref_alloc_qty, 0) > 0 ), stage_2_wh_group_stock AS ( SELECT sku_group, belt_size, wh_group, SUM(remaining_facility_stock) AS remaining_group_stock FROM facility_stock_after_stage_1 GROUP BY 1, 2, 3 ), stage_2_demand_ranked AS ( SELECT d.*, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, belt_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_fallback, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, belt_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_fallback_before FROM stage_2_remaining_demand d ), stage_2_group_alloc AS ( SELECT d.*, COALESCE(w.remaining_group_stock, 0) AS fallback_group_stock, GREATEST( LEAST(d.cum_need_fallback, COALESCE(w.remaining_group_stock, 0)) - COALESCE(d.cum_need_fallback_before, 0), 0 ) AS fallback_alloc_qty FROM stage_2_demand_ranked d LEFT JOIN stage_2_wh_group_stock w ON w.sku_group = d.sku_group AND w.belt_size = d.belt_size AND w.wh_group = d.fallback_wh_group ), stage_2_alloc_ranked_for_facility AS ( SELECT *, SUM(fallback_alloc_qty) OVER ( PARTITION BY sku_group, belt_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fallback_alloc, SUM(fallback_alloc_qty) OVER ( PARTITION BY sku_group, belt_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fallback_alloc_before FROM stage_2_group_alloc WHERE fallback_alloc_qty > 0 ), stage_2_facility_stock_ranked AS ( SELECT *, SUM(remaining_facility_stock) OVER ( PARTITION BY sku_group, belt_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_remaining_fac_stock, SUM(remaining_facility_stock) OVER ( PARTITION BY sku_group, belt_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_remaining_fac_stock_before FROM facility_stock_after_stage_1 WHERE remaining_facility_stock > 0 ), stage_2_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, d.belt_size, w.size_sku_code, w.facility, w.wh_group, \'FALLBACK_WH\' AS allocation_stage, d.physical_size_qty, d.jit_size_qty, d.current_size_available, d.inventory_qty, d.jit_qty, d.stock_qty, d.size_status, d.size_remark, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_10_day_cover, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_size_inventory AS warehouse_size_stock, GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_2_alloc_ranked_for_facility d JOIN stage_2_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.belt_size = d.belt_size AND w.wh_group = d.fallback_wh_group WHERE GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) > 0 ), final_allocation AS ( SELECT * FROM stage_1_facility_alloc UNION ALL SELECT * FROM stage_2_facility_alloc ) SELECT branch_code, branch_name, region, sku_group, belt_size, size_sku_code, facility AS warehouse_name, wh_group, allocation_stage, physical_size_qty, jit_size_qty, current_size_available, target_10_day_cover, need_qty, allocated_qty, warehouse_size_stock, inventory_qty AS store_inventory_qty, jit_qty AS store_jit_qty, stock_qty AS store_stock_jit_qty, size_status, size_remark, replen_priority_bucket, replen_priority_reason, option_count, ideal_options, current_options, option_gap, store_size, sales_last_7_days, sales_last_15_days, sales_last_30_days, ROUND(ros, 4) AS ros, ROUND(str, 4) AS str, ROUND(sell_through, 4) AS store_sell_through, preferred_wh_group, fallback_wh_group FROM final_allocation WHERE allocated_qty > 0 ORDER BY replen_priority_bucket ASC, sku_group, belt_size, CASE WHEN allocation_stage = \'PREFERRED_WH\' THEN 1 ELSE 2 END, store_sell_through DESC, option_gap DESC, store_size DESC, ros DESC, branch_code, warehouse_name ), PERFUMES AS ( WITH store_sku_inventory AS ( SELECT *, COUNT(DISTINCT sku_group) OVER ( PARTITION BY branch_code, branch_name ) AS option_count FROM ( SELECT h.branch_code, UPPER(TRIM(h.marketplace_mapped)) AS branch_name, CASE WHEN UPPER(TRIM(h.sku_group)) = \'4MSFR0941-01\' THEN \'4MSFR0941-01-01\' WHEN UPPER(TRIM(h.sku_group)) = \'4MSFR0942-01\' THEN \'4MSFR0942-01-01\' WHEN UPPER(TRIM(h.sku_group)) = \'4MSFR0943-01\' THEN \'4MSFR0943-01-01\' ELSE UPPER(TRIM(h.sku_group)) END AS sku_group, SUM(COALESCE(h.inventory, 0)) AS inventory_qty, SUM(COALESCE(h.jit_qty, 0)) AS jit_qty, SUM(COALESCE(h.inventory, 0)) + SUM(COALESCE(h.jit_qty, 0)) AS stock_qty, SUM(COALESCE(h.sales_last_30_days, 0)) AS sales_last_30_days, SUM(COALESCE(h.sales_last_15_days, 0)) AS sales_last_15_days, SUM(COALESCE(h.sales_last_7_days, 0)) AS sales_last_7_days, ( 0.5 * (SUM(COALESCE(h.sales_last_7_days, 0)) / 7.0) + 0.3 * (SUM(COALESCE(h.sales_last_15_days, 0)) / 15.0) + 0.2 * (SUM(COALESCE(h.sales_last_30_days, 0)) / 30.0) ) AS ros, SUM(COALESCE(h.sales_last_30_days, 0)) / NULLIF( SUM(COALESCE(h.sales_last_30_days, 0)) + SUM(COALESCE(h.inventory, 0)), 0 ) AS str FROM snitch_db.maplemonk.offline_master h WHERE UPPER(TRIM(h.sku_group)) LIKE \'4MSFR%\' AND COALESCE(h.inventory, 0) + COALESCE(h.jit_qty, 0) > 0 AND UPPER(TRIM(h.sku_group)) NOT IN (\'4MSFR0936-02%\',\'4MSFR0936-05%\',\'4MSFR0930\',\'4MSFR0931\') GROUP BY h.branch_code, UPPER(TRIM(h.marketplace_mapped)), CASE WHEN UPPER(TRIM(h.sku_group)) = \'4MSFR0941-01\' THEN \'4MSFR0941-01-01\' WHEN UPPER(TRIM(h.sku_group)) = \'4MSFR0942-01\' THEN \'4MSFR0942-01-01\' WHEN UPPER(TRIM(h.sku_group)) = \'4MSFR0943-01\' THEN \'4MSFR0943-01-01\' ELSE UPPER(TRIM(h.sku_group)) END ) t ), stores_perf AS ( SELECT DISTINCT branch_code, branch_name AS marketplace_mapped FROM store_sku_inventory ), store_option_count AS ( SELECT branch_code, branch_name AS marketplace_mapped, MAX(option_count) AS option_count FROM store_sku_inventory GROUP BY 1, 2 ), store_region AS ( SELECT DISTINCT branch_code, UPPER(TRIM(zone)) AS region FROM snitch_db.maplemonk.store_category_delta ), schedule_rpl AS ( SELECT branch_code, UPPER(LEFT( CASE WHEN UPPER(cluster) IN (\'BANGALORE\', \'KARNATAKA\') AND UPPER(LEFT(south_rpl, 3)) = \'WED\' THEN \'TUE\' WHEN zone = \'South\' THEN south_rpl ELSE north_rpl END, 3 )) AS rpl_order_day FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY branch_code) AS rn FROM snitch_db.maplemonk.store_category_delta ) t WHERE rn = 1 QUALIFY ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY rpl_order_day) = 1 ), store_sell_through AS ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS marketplace_mapped, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( (SUM(COALESCE(opening_inventory, 0)) + SUM(COALESCE(inventory, 0))) / 2.0, 0 ) AS sell_through FROM snitch_db.maplemonk.off_master_htmlbase WHERE UPPER(TRIM(sku_group)) LIKE \'4MSFR%\' GROUP BY 1, 2 ), store_ideal_options AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(\"Perfume(Options)\" AS INT), 0) AS ideal_options FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_size AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(REPLACE(sqft, \',\', \'\') AS INT), 0) AS store_size FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_priority AS ( SELECT s.branch_code, s.marketplace_mapped, COALESCE(sr.region, \'UNKNOWN\') AS region, COALESCE(st.sell_through, 0) AS sell_through, COALESCE(io.ideal_options, 0) AS ideal_options, COALESCE(oc.option_count, 0) AS current_options, COALESCE(io.ideal_options, 0) - COALESCE(oc.option_count, 0) AS option_gap, COALESCE(sz.store_size, 0) AS store_size FROM stores_perf s LEFT JOIN store_region sr ON sr.branch_code = s.branch_code LEFT JOIN store_sell_through st ON st.branch_code = s.branch_code AND st.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_option_count oc ON oc.branch_code = s.branch_code AND oc.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_ideal_options io ON io.branch_code = s.branch_code LEFT JOIN store_size sz ON sz.branch_code = s.branch_code INNER JOIN schedule_rpl sch ON sch.branch_code = s.branch_code AND UPPER(TRIM(sch.rpl_order_day)) = UPPER(DAYNAME(CURRENT_DATE)) ), wh_raw AS ( SELECT facility, UPPER(TRIM(\"Item SkuCode\")) AS sku_group, COALESCE(inventory, 0) AS inventory FROM snitch_db.maplemonk.unicommerce_live_inventory WHERE facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') AND UPPER(TRIM(\"Item SkuCode\")) LIKE \'4MSFR%\' AND INVENTORY > 12 AND UPPER(TRIM(\"Item SkuCode\")) NOT IN (\'4MSFR0936-02%\',\'4MSFR0936-05%\',\'4MSFR0930\',\'4MSFR0931\') ), perfume_wh_inventory AS ( SELECT facility, CASE WHEN facility IN (\'SAPL-WH2\', \'SAPL-WH1\') THEN \'SOUTH_WH\' WHEN facility = \'SAPL-NORTH-TAURU\' THEN \'NORTH_WH\' ELSE \'OTHER_WH\' END AS wh_group, CASE WHEN facility = \'SAPL-WH2\' THEN 1 WHEN facility = \'SAPL-WH1\' THEN 2 WHEN facility = \'SAPL-NORTH-TAURU\' THEN 3 ELSE 9 END AS facility_order, sku_group, FLOOR(SUM(inventory) / 12.0) * 12 AS wh_inventory FROM wh_raw GROUP BY facility, sku_group HAVING FLOOR(SUM(inventory) / 12.0) * 12 >= 12 ), replen_demand_base AS ( SELECT s.branch_code, s.branch_name, s.sku_group, s.inventory_qty, s.jit_qty, s.stock_qty, s.option_count, s.sales_last_30_days, s.sales_last_15_days, s.sales_last_7_days, s.ros, s.str, GREATEST(12, CEIL(s.ros * 10)) AS target_qty, sp.region, sp.sell_through, sp.ideal_options, sp.current_options, sp.option_gap, sp.store_size, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'NORTH_WH\' ELSE \'SOUTH_WH\' END AS preferred_wh_group, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'SOUTH_WH\' ELSE \'NORTH_WH\' END AS fallback_wh_group FROM store_sku_inventory s LEFT JOIN store_priority sp ON sp.branch_code = s.branch_code AND sp.marketplace_mapped = s.branch_name ), replen_demand AS ( SELECT *, CASE WHEN target_qty > COALESCE(stock_qty, 0) THEN CEIL((target_qty - COALESCE(stock_qty, 0)) / 12.0) * 12 ELSE 0 END AS need_qty, CASE WHEN COALESCE(stock_qty, 0) < 12 THEN 1 WHEN target_qty > COALESCE(stock_qty, 0) THEN 2 ELSE 3 END AS replen_priority_bucket, CASE WHEN COALESCE(stock_qty, 0) < 12 THEN \'MIN_12_QTY_REPLEN\' WHEN target_qty > COALESCE(stock_qty, 0) THEN \'ROS_10_DAY_TOPUP\' ELSE \'OTHER\' END AS replen_priority_reason FROM replen_demand_base WHERE target_qty > COALESCE(stock_qty, 0) ), wh_group_stock AS ( SELECT sku_group, wh_group, SUM(wh_inventory) AS group_stock FROM perfume_wh_inventory GROUP BY 1, 2 ), stage_1_demand_ranked AS ( SELECT d.*, SUM(need_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_pref, SUM(need_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_pref_before FROM replen_demand d ), stage_1_group_alloc AS ( SELECT d.*, COALESCE(w.group_stock, 0) AS preferred_group_stock, GREATEST( LEAST(d.cum_need_pref, COALESCE(w.group_stock, 0)) - COALESCE(d.cum_need_pref_before, 0), 0 ) AS pref_alloc_qty FROM stage_1_demand_ranked d LEFT JOIN wh_group_stock w ON w.sku_group = d.sku_group AND w.wh_group = d.preferred_wh_group ), stage_1_alloc_ranked_for_facility AS ( SELECT *, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_pref_alloc, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_pref_alloc_before FROM stage_1_group_alloc WHERE pref_alloc_qty > 0 ), stage_1_facility_stock_ranked AS ( SELECT *, SUM(wh_inventory) OVER ( PARTITION BY sku_group, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fac_stock, SUM(wh_inventory) OVER ( PARTITION BY sku_group, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fac_stock_before FROM perfume_wh_inventory ), stage_1_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, w.facility, w.wh_group, \'PREFERRED_WH\' AS allocation_stage, d.inventory_qty, d.jit_qty, d.stock_qty, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_qty, d.need_qty, d.sell_through, d.ideal_options, d.current_opti