s, d.str, d.target_qty, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_inventory AS warehouse_stock, GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_2_alloc_ranked_for_facility d JOIN stage_2_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.wh_group = d.fallback_wh_group WHERE GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) > 0 ), final_allocation AS ( SELECT * FROM stage_1_facility_alloc UNION ALL SELECT * FROM stage_2_facility_alloc ) SELECT branch_code, branch_name, region, sku_group, NULL AS product_size, NULL AS size_sku_code, facility AS warehouse_name, wh_group, allocation_stage, NULL AS physical_size_qty, NULL AS jit_size_qty, NULL AS current_size_available, target_qty, need_qty, allocated_qty, warehouse_stock, inventory_qty AS store_inventory_qty, jit_qty AS store_jit_qty, stock_qty AS store_stock_jit_qty, NULL AS size_status, NULL AS size_remark, replen_priority_bucket, replen_priority_reason, option_count, ideal_options, current_options, option_gap, store_size, sales_last_7_days, sales_last_15_days, sales_last_30_days, ROUND(ros, 4) AS ros, ROUND(str, 4) AS str, ROUND(sell_through, 4) AS store_sell_through, preferred_wh_group, fallback_wh_group FROM final_allocation WHERE allocated_qty > 0 ORDER BY replen_priority_bucket ASC, sku_group, CASE WHEN allocation_stage = \'PREFERRED_WH\' THEN 1 ELSE 2 END, store_sell_through DESC, option_gap DESC, store_size DESC, ros DESC, branch_code, warehouse_name ), BAGS AS ( WITH store_sku_inventory AS ( SELECT *, COUNT(DISTINCT sku_group) OVER ( PARTITION BY branch_code, branch_name ) AS option_count FROM ( SELECT h.branch_code, UPPER(TRIM(h.marketplace_mapped)) AS branch_name, UPPER(TRIM(h.sku_group)) AS sku_group, SUM(COALESCE(h.inventory, 0)) AS inventory_qty, SUM(COALESCE(h.jit_qty, 0)) AS jit_qty, SUM(COALESCE(h.inventory, 0)) + SUM(COALESCE(h.jit_qty, 0)) AS stock_qty, SUM(COALESCE(h.sales_last_30_days, 0)) AS sales_last_30_days, SUM(COALESCE(h.sales_last_15_days, 0)) AS sales_last_15_days, SUM(COALESCE(h.sales_last_7_days, 0)) AS sales_last_7_days, ( 0.5 * (SUM(COALESCE(h.sales_last_7_days, 0)) / 7.0) + 0.3 * (SUM(COALESCE(h.sales_last_15_days, 0)) / 15.0) + 0.2 * (SUM(COALESCE(h.sales_last_30_days, 0)) / 30.0) ) AS ros, SUM(COALESCE(h.sales_last_30_days, 0)) / NULLIF( SUM(COALESCE(h.sales_last_30_days, 0)) + SUM(COALESCE(h.inventory, 0)), 0 ) AS str FROM snitch_db.maplemonk.offline_master h WHERE UPPER(TRIM(h.sku_group)) LIKE \'BP%\' AND COALESCE(h.inventory, 0) + COALESCE(h.jit_qty, 0) > 0 GROUP BY h.branch_code, UPPER(TRIM(h.marketplace_mapped)), UPPER(TRIM(h.sku_group)) ) ), stores_perf AS ( SELECT DISTINCT branch_code, branch_name AS marketplace_mapped FROM store_sku_inventory ), store_option_count AS ( SELECT branch_code, branch_name AS marketplace_mapped, MAX(option_count) AS option_count FROM store_sku_inventory GROUP BY 1, 2 ), store_region AS ( SELECT DISTINCT branch_code, UPPER(TRIM(zone)) AS region FROM snitch_db.maplemonk.store_category_delta ), schedule_rpl AS ( SELECT branch_code, UPPER(LEFT( CASE WHEN UPPER(cluster) IN (\'BANGALORE\', \'KARNATAKA\') AND UPPER(LEFT(south_rpl, 3)) = \'WED\' THEN \'TUE\' WHEN zone = \'South\' THEN south_rpl ELSE north_rpl END, 3 )) AS rpl_order_day FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY branch_code) AS rn FROM snitch_db.maplemonk.store_category_delta ) t WHERE rn = 1 QUALIFY ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY rpl_order_day) = 1 ), store_sell_through AS ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS marketplace_mapped, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( (SUM(COALESCE(opening_inventory, 0)