code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_pref_before FROM replen_demand d ), stage_1_group_alloc AS ( SELECT d.*, COALESCE(w.group_stock, 0) AS preferred_group_stock, GREATEST( LEAST(d.cum_need_pref, COALESCE(w.group_stock, 0)) - COALESCE(d.cum_need_pref_before, 0), 0 ) AS pref_alloc_qty FROM stage_1_demand_ranked d LEFT JOIN wh_group_stock w ON w.sku_group = d.sku_group AND w.wh_group = d.preferred_wh_group ), stage_1_alloc_ranked_for_facility AS ( SELECT *, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_pref_alloc, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_pref_alloc_before FROM stage_1_group_alloc WHERE pref_alloc_qty > 0 ), stage_1_facility_stock_ranked AS ( SELECT *, SUM(wh_inventory) OVER ( PARTITION BY sku_group, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fac_stock, SUM(wh_inventory) OVER ( PARTITION BY sku_group, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fac_stock_before FROM bags_wh_inventory ), stage_1_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, w.facility, w.wh_group, \'PREFERRED_WH\' AS allocation_stage, d.inventory_qty, d.jit_qty, d.stock_qty, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_qty, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh