up)) AS sku_group, SUM(COALESCE(h.inventory, 0)) AS inventory_qty, SUM(COALESCE(h.jit_qty, 0)) AS jit_qty, SUM(COALESCE(h.inventory, 0)) + SUM(COALESCE(h.jit_qty, 0)) AS stock_qty, SUM(COALESCE(h.sales_last_30_days, 0)) AS sales_last_30_days, SUM(COALESCE(h.sales_last_15_days, 0)) AS sales_last_15_days, SUM(COALESCE(h.sales_last_7_days, 0)) AS sales_last_7_days, ( 0.5 * (SUM(COALESCE(h.sales_last_7_days, 0)) / 7.0) + 0.3 * (SUM(COALESCE(h.sales_last_15_days, 0)) / 15.0) + 0.2 * (SUM(COALESCE(h.sales_last_30_days, 0)) / 30.0) ) AS ros, SUM(COALESCE(h.sales_last_30_days, 0)) / NULLIF( SUM(COALESCE(h.sales_last_30_days, 0)) + SUM(COALESCE(h.inventory, 0)), 0 ) AS str FROM snitch_db.maplemonk.offline_master h WHERE UPPER(TRIM(h.sku_group)) LIKE \'4MCP%\' AND COALESCE(h.inventory, 0) + COALESCE(h.jit_qty, 0) > 0 GROUP BY h.branch_code, UPPER(TRIM(h.marketplace_mapped)), UPPER(TRIM(h.sku_group)) ) ), stores_perf AS ( SELECT DISTINCT branch_code, branch_name AS marketplace_mapped FROM store_sku_inventory ), store_option_count AS ( SELECT branch_code, branch_name AS marketplace_mapped, MAX(option_count) AS option_count FROM store_sku_inventory GROUP BY 1, 2 ), store_region AS ( SELECT DISTINCT branch_code, UPPER(TRIM(zone)) AS region FROM snitch_db.maplemonk.store_category_delta ), schedule_rpl AS ( SELECT branch_code, UPPER(LEFT( CASE WHEN UPPER(cluster) IN (\'BANGALORE\', \'KARNATAKA\') AND UPPER(LEFT(south_rpl, 3)) = \'WED\' THEN \'TUE\' WHEN zone = \'South\' THEN south_rpl ELSE north_rpl END, 3 )) AS rpl_order_day FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY branch_code) AS rn FROM snitch_db.maplemonk.store_category_delta ) t WHERE rn = 1 QUALIFY ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY rpl_order_day) = 1 ), store_sell_through AS ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS marketplace_mapped, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( (SUM(COALESCE(opening_inventory, 0)) + SUM(COALESCE(inventory, 0))) / 2.0, 0 ) AS sell_through FROM snitch_db.maplemonk.off_master_htmlbase WHERE UPPER(TRIM(sku_group)) LIKE \'4MCP%\' GROUP BY 1, 2 ), store_ideal_options AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(\"Belts(Options)\" AS INT), 0) AS ideal_options FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_size AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(REPLACE(sqft, \',\', \'\') AS INT), 0) AS store_size FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_priority AS ( SELECT s.branch_code, s.marketplace_mapped, COALESCE(sr.region, \'UNKNOWN\') AS region, COALESCE(st.sell_through, 0) AS sell_through, COALESCE(io.ideal_options, 0) AS ideal_options, COALESCE(oc.option_count, 0) AS current_options, COALESCE(io.ideal_options, 0) - COALESCE(oc.option_count, 0) AS option_gap, COALESCE(sz.store_size, 0) AS store_size FROM stores_perf s LEFT JOIN store_region sr ON sr.branch_code = s.branch_code LEFT JOIN store_sell_through st ON st.branch_code = s.branch_code AND st.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_option_count oc ON oc.branch_code = s.branch_code AND oc.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_ideal_options io ON io.branch_code = s.branch_code LEFT JOIN store_size sz ON sz.branch_code = s.branch_code INNER JOIN schedule_rpl sch ON sch.branch_code = s.branch_code AND UPPER(TRIM(sch.rpl_order_day)) = UPPER(DAYNAME(CURRENT_DATE)) ), wh_raw AS ( SELECT facility, UPPER(TRIM(\"Item SkuCode\")) AS sku_group, COALESCE(inventory, 0) AS inventory FROM snitch_db.maplemonk.unicommerce_live_inventory WHERE facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') AND UPPER(TRIM(\"Item SkuCode\")) LIKE \'4MCP%\' AND INVENTORY > 5 ), caps_wh_inventory AS ( SELECT facility, CASE WHEN facility IN (\'SAPL-WH2\', \'SAPL-WH1\') THEN \'SOUTH_WH\' WHEN facility = \'SAPL-NORTH-TAURU\' THEN \'NORTH_WH\' ELSE \'OTHER_WH\' END AS wh_group, CASE WHEN facility = \'SAPL-WH2\' THEN 1 WHEN facility = \'SAPL-WH1\' THEN 2 WHEN facility = \'SAPL-NORTH-TAURU\' THEN 3 ELSE 9 END AS facility_order, sku_group, SUM(inventory) AS wh_inventory FROM wh_raw GROUP BY facility, sku_group HAVING SUM(inventory) > 0 ), replen_demand_base AS ( SELECT s.branch_code, s.branch_name, s.sku_group, s.inventory_qty, s.jit_qty, s.stock_qty, s.option_count, s.sales_last_30_days, s.sales_last_15_days, s.sales_last_7_days, s.ros, s.str, GREATEST(4, CEIL(s.ros * 10)) AS target_qty, sp.region, sp.sell_through, sp.ideal_options, sp.current_options, sp.option_gap, sp.store_size, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'NORTH_WH\' ELSE \'SOUTH_WH\' END AS preferred_wh_group, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'SOUTH_WH\' ELSE \'NORTH_WH\' END AS fallback_wh_group FROM store_sku_inventory s LEFT JOIN store_priority sp ON sp.branch_code = s.branch_code AND sp.marketplace_mapped = s.branch_name ), replen_demand AS ( SELECT *, GREATEST(target_qty - COALESCE(stock_qty, 0), 0) AS need_qty, CASE WHEN COALESCE(stock_qty, 0) < 4 THEN 1 WHEN target_qty > COALESCE(stock_qty, 0) THEN 2 ELSE 3 END AS replen_priority_bucket, CASE WHEN COALESCE(stock_qty, 0) < 4 THEN \'MIN_4_QTY_REPLEN\' WHEN target_qty > COALESCE(stock_qty, 0) THEN \'ROS_10_DAY_TOPUP\' ELSE \'OTHER\' END AS replen_priority_reason FROM replen_demand_base WHERE target_qty > COALESCE(stock_qty, 0) ), wh_group_stock AS ( SELECT sku_group, wh_group, SUM(wh_inventory) AS group_stock FROM caps_wh_inventory GROUP BY 1, 2 ), stage_1_demand_ranked AS ( SELECT d.*, SUM(need_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_pref, SUM(need_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_pref_before FROM replen_demand d ), stage_1_group_alloc AS ( SELECT d.*, COALESCE(w.group_stock, 0) AS preferred_group_stock, GREATEST( LEAST(d.cum_need_pref, COALESCE(w.group_stock, 0)) - COALESCE(d.cum_need_pref_before, 0), 0 ) AS pref_alloc_qty FROM stage_1_demand_ranked d LEFT JOIN wh_group_stock w ON w.sku_group = d.sku_group AND w.wh_group = d.preferred_wh_group ), stage_1_alloc_ranked_for_facility AS ( SELECT *, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_pref_alloc, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_pref_alloc_before FROM stage_1_group_alloc WHERE pref_alloc_qty > 0 ), stage_1_facility_stock_ranked AS ( SELECT *, SUM(wh_inventory) OVER ( PARTITION BY sku_group, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fac_stock, SUM(wh_inventory) OVER ( PARTITION BY sku_group, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fac_stock_before FROM caps_wh_inventory ), stage_1_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, w.facility, w.wh_group, \'PREFERRED_WH\' AS allocation_stage, d.inventory_qty, d.jit_qty, d.stock_qty, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_qty, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_inventory AS warehouse_stock, GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_1_alloc_ranked_for_facility d JOIN stage_1_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.wh_group = d.preferred_wh_group WHERE GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) > 0 ), stage_1_facility_consumed AS ( SELECT sku_group, facility, SUM(allocated_qty) AS consumed_qty FROM stage_1_facility_alloc GROUP BY 1, 2 ), facility_stock_after_stage_1 AS ( SELECT w.sku_group, w.facility, w.wh_group, w.facility_order, w.wh_inventory, COALESCE(c.consumed_qty, 0) AS consumed_stage_1_qty, GREATEST(w.wh_inventory - COALESCE(c.consumed_qty, 0), 0) AS remaining_facility_stock FROM caps_wh_inventory w LEFT JOIN stage_1_facility_consumed c ON c.sku_group = w.sku_group AND c.facility = w.facility ), stage_2_remaining_demand AS ( SELECT *, GREATEST(need_qty - pref_alloc_qty, 0) AS remaining_need_qty FROM stage_1_group_alloc WHERE GREATEST(need_qty - pref_alloc_qty, 0) > 0 ), stage_2_wh_group_stock AS ( SELECT sku_group, wh_group, SUM(remaining_facility_stock) AS remaining_group_stock FROM facility_stock_after_stage_1 GROUP BY 1, 2 ), stage_2_demand_ranked AS ( SELECT d.*, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_fallback, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_fallback_before FROM stage_2_remaining_demand d ), stage_2_group_alloc AS ( SELECT d.*, COALESCE(w.remaining_group_stock, 0) AS fallback_group_stock, GREATEST( LEAST(d.cum_need_fallback, COALESCE(w.remaining_group_stock, 0)) - COALESCE(d.cum_need_fallback_before, 0), 0 ) AS fallback_alloc_qty FROM stage_2_demand_ranked d LEFT JOIN stage_2_wh_group_stock w ON w.sku_group = d.sku_group AND w.wh_group = d.fallback_wh_group ), stage_2_alloc_ranked_for_facility AS ( SELECT *, SUM(fallback_alloc_qty) OVER ( PARTITION BY sku_group, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fallback_alloc, SUM(fallback_alloc_qty) OVER ( PARTITION BY sku_group, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fallback_alloc_before FROM stage_2_group_alloc WHERE fallback_alloc_qty > 0 ), stage_2_facility_stock_ranked AS ( SELECT *, SUM(remaining_facility_stock) OVER ( PARTITION BY sku_group, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_remaining_fac_stock, SUM(remaining_facility_stock) OVER ( PARTITION BY sku_group, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_remaining_fac_stock_before FROM facility_stock_after_stage_1 WHERE remaining_facility_stock > 0 ), stage_2_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, w.facility, w.wh_group, \'FALLBACK_WH\' AS allocation_stage, d.inventory_qty, d.jit_qty, d.stock_qty, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_qty, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_inventory AS warehouse_stock, GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_2_alloc_ranked_for_facility d JOIN stage_2_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.wh_group = d.fallback_wh_group WHERE GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) > 0 ), final_allocation AS ( SELECT * FROM stage_1_facility_alloc UNION ALL SELECT * FROM stage_2_facility_alloc ) SELECT branch_code, branch_name, region, sku_group, NULL AS product_size, NULL AS size_sku_code, facility AS warehouse_name, wh_group, allocation_stage, NULL AS physical_size_qty, NULL AS jit_size_qty, NULL AS current_size_available, target_qty, need_qty, allocated_qty, warehouse_stock, inventory_qty AS store_inventory_qty, jit_qty AS store_jit_qty, stock_qty AS store_stock_jit_qty, NULL AS size_status, NULL AS size_remark, replen_priority_bucket, replen_priority_reason, option_count, ideal_options, current_options, option_gap, store_size, sales_last_7_days, sales_last_15_days, sales_last_30_days, ROUND(ros, 4) AS ros, ROUND(str, 4) AS str, ROUND(sell_through, 4) AS store_sell_through, preferred_wh_group, fallback_wh_group FROM final_allocation WHERE allocated_qty > 0 ORDER BY replen_priority_bucket ASC, sku_group, CASE WHEN allocation_stage = \'PREFERRED_WH\' THEN 1 ELSE 2 END, store_sell_through DESC, option_gap DESC, store_size DESC, ros DESC, branch_code, warehouse_name ), SUNGLASSES AS ( WITH store_sku_inventory AS ( SELECT *, COUNT(DISTINCT sku_group) OVER ( PARTITION BY branch_code, branch_name ) AS option_count FROM ( SELECT h.branch_code, UPPER(TRIM(h.marketplace_mapped)) AS branch_name, UPPER(TRIM(h.sku_group)) AS sku_group, SUM(COALESCE(h.inv